// ==================== VAG 1: DATABASE ER AGE ====================

// টেক্সট ক্লিন করার নিয়ম (সব LaTeX সংকেত, ব্যাকস্ল্যাশ ও স্পেস বাদ দিয়ে তুলনা করা)
function cleanMathText(str) {
  return (str || '').replace(/[\\$\s{}()]/g, '').trim().toLowerCase();
}

// ডুপ্লিকেট প্রশ্ন গ্রুপ করার ফাংশন
function getDuplicateInfo(db) {
  const countMap = {};
  if (!Array.isArray(db)) return countMap;

  db.forEach(item => {
    if (!item || !item.question) return;
    const key = cleanMathText(item.question);
    if (!countMap[key]) {
      countMap[key] = [];
    }
    countMap[key].push(item.id);
  });

  return countMap;
}


