    question: "যদি $a = \\sqrt{3} + \\sqrt{2}$ হয়, তবে প্রমাণ করুন যে, $a^3 + \\frac{1}{a^3} = 18\\sqrt{3}$",
    solution: `
      দেওয়া আছে, $a = \\sqrt{3} + \\sqrt{2}$<br><br>
      $\\therefore \\frac{1}{a} = \\frac{1}{\\sqrt{3} + \\sqrt{2}} = \\frac{\\sqrt{3} - \\sqrt{2}}{(\\sqrt{3} + \\sqrt{2})(\\sqrt{3} - \\sqrt{2})} = \\frac{\\sqrt{3} - \\sqrt{2}}{(\\sqrt{3})^2 - (\\sqrt{2})^2} = \\sqrt{3} - \\sqrt{2}$<br><br>
      $\\therefore a + \\frac{1}{a} = (\\sqrt{3} + \\sqrt{2}) + (\\sqrt{3} - \\sqrt{2}) = 2\\sqrt{3}$<br><br>
      বামপক্ষ $= a^3 + \\frac{1}{a^3}$<br>
      $= \\left(a + \\frac{1}{a}\\right)^3 - 3 \\cdot a \\cdot \\frac{1}{a} \\left(a + \\frac{1}{a}\\right)$<br>
      $= (2\\sqrt{3})^3 - 3(2\\sqrt{3})$<br>
      $= 24\\sqrt{3} - 6\\sqrt{3} = 18\\sqrt{3}$ = ডানপক্ষ<br><br>
      <b>(প্রমাণিত)</b>
    `
