    solution: `
      ধরি, বড় সংখ্যাটি = $x$ এবং ছোট সংখ্যাটি = $y$<br><br>
      প্রশ্নমতে,<br>
      $x + y = ১৫$ ... (i)<br>
      $x - y = ১৩$ ... (ii)<br><br>
      (i) নং সমীকরণ থেকে (ii) নং সমীকরণ বিয়োগ করে পাই,<br>
      $২y = ২$<br>
      $\\Rightarrow y = \\frac{২}{২} = ১$<br><br>
      $\\therefore$ ছোট সংখ্যাটি = ১।<br><br>
      <b>উত্তর:</b> ১
    `
