    solution: `
      দেওয়া আছে,<br>
      ত্রিভুজক্ষেত্রের ক্ষেত্রফল = ৮৪ বর্গগজ<br>
      লম্বের দৈর্ঘ্য (উচ্চতা, $h$) = ১২ গজ<br>
      ভূমির দৈর্ঘ্য ($b$) = ?<br><br>
      আমরা জানি,<br>
      ত্রিভুজক্ষেত্রের ক্ষেত্রফল $= \\frac{১}{২} \\times \\text{ভূমি} \\times \\text{উচ্চতা}$<br>
      $\\Rightarrow \\text{ভূমি} = \\frac{২ \\times \\text{ক্ষেত্রফল}}{\\text{উচ্চতা}}$<br>
      $= \\frac{২ \\times ৮৪}{১২}$ গজ<br>
      $= ২ \\times ৭ = ১৪$ গজ।<br><br>
      <b>উত্তর:</b> ১৪ গজ।
    `
