    question: "উৎপাদকে বিশ্লেষণ করুন: $336x^3 + 370x^2 - 457x - 504$",
    solution: `
      প্রদত্ত রাশি = $336x^3 + 370x^2 - 457x - 504$<br>
      $= 336x^3 - 392x^2 + 762x^2 - 889x + 432x - 504$<br>
      $= 56x^2(6x - 7) + 127x(6x - 7) + 72(6x - 7)$<br>
      $= (6x - 7)(56x^2 + 127x + 72)$<br>
      $= (6x - 7)(56x^2 + 64x + 63x + 72)$<br>
      $= (6x - 7)[8x(7x + 8) + 9(7x + 8)]$<br>
      $= (6x - 7)(7x + 8)(8x + 9)$<br><br>
      <b>উত্তর:</b> $(6x - 7)(7x + 8)(8x + 9)$
    `
