    question: "একটি ত্রিভুজের তিনটি বাহুর দৈর্ঘ্য যথাক্রমে ৭ সেমি., ৮ সেমি. ও ৯ সেমি.। ত্রিভুজটির ক্ষেত্রফল নির্ণয় করুন।",
    solution: `
      এখানে বাহুত্রয়, $a = ৭$ সেমি., $b = ৮$ সেমি. এবং $c = ৯$ সেমি.<br><br>
      ত্রিভুজটির অর্ধপরিসীমা, $s = \\frac{a + b + c}{২}$<br>
      $= \\frac{৭ + ৮ + ৯}{২} = \\frac{২৪}{২} = ১২$ সেমি.<br><br>
      আমরা জানি, বিষমবাহু ত্রিভুজের ক্ষেত্রফল $= \\sqrt{s(s - a)(s - b)(s - c)}$<br>
      $= \\sqrt{১২(১২ - ৭)(১২ - ৮)(১২ - ৯)}$ বর্গসেমি.<br>
      $= \\sqrt{১২ \\times ৫ \\times ৪ \\times ৩}$ বর্গসেমি.<br>
      $= \\sqrt{৭২০}$ বর্গসেমি.<br>
      $= \\sqrt{১৪৪ \\times ৫} = ১২\\sqrt{৫}$ বর্গসেমি.<br><br>
      <b>উত্তর:</b> $১২\\sqrt{৫}$ বর্গ সেমি.।
    `
