    solution: `
      <b>সমকোণ:</b> যে কোণের পরিমাণ ৯০° তাকে সমকোণ বলে। একটি সরলরেখার ওপর অন্য একটি লম্ব দণ্ডায়মান হলে উৎপন্ন সন্নিহিত কোণদ্বয় প্রত্যেকে এক সমকোণ।<br><br>
      <b>বিপ্রতীপ কোণ:</b> কোনো কোণের বাহুদ্বয়ের বিপরীত রশ্মিদ্বয় যে কোণ তৈরি করে, তাকে ওই কোণের বিপ্রতীপ কোণ বলে। দুটি সরলরেখা পরস্পর ছেদ করলে চারটি কোণ উৎপন্ন হয়, এদের বিপরীত পাশের কোণ দুটি পরস্পরের বিপ্রতীপ কোণ (এরা পরস্পর সমান)।
    `
