    question: "যদি $x - \\frac{1}{x} = 1$ হয়, তবে দেখাও যে, $x^3 - \\frac{1}{x^3} = 4$",
    solution: `
      দেওয়া আছে, $x - \\frac{1}{x} = 1$<br><br>
      বামপক্ষ $= x^3 - \\frac{1}{x^3}$<br>
      $= \\left(x - \\frac{1}{x}\\right)^3 + 3 \\cdot x \\cdot \\frac{1}{x} \\left(x - \\frac{1}{x}\\right)$<br>
      $= (1)^3 + 3(1)$<br>
      $= 1 + 3 = 4$<br>
      $= $ ডানপক্ষ<br><br>
      <b>(দেখানো হলো)</b>
    `
