    examYear: "২০২৪",
    question: "একটি দ্রব্য ৫০০০ টাকায় ক্রয় করে ১৫% লাভে বিক্রয় করা হলো। দ্রব্যটির ক্রয়মূল্য ১০% কম হলে কত টাকা লাভ হবে?",
    solution: `
      দেওয়া আছে, প্রকৃত ক্রয়মূল্য = ৫,০০০ টাকা<br><br>
      ১৫% লাভে বিক্রয়মূল্য $= ৫০০০ + (৫০০০ \\text{ এর } ১৫\\%)$<br>
      $= ৫০০০ + ৭৫০ = ৫,৭৫০$ টাকা<br><br>
      ক্রয়মূল্য ১০% কম হলে,<br>
      নতুন ক্রয়মূল্য $= ৫০০০ - (৫০০০ \\text{ এর } ১০\\%)$<br>
      $= ৫০০০ - ৫০০ = ৪,৫০০$ টাকা<br><br>
      $\\therefore$ তখন লাভ হবে $= (৫৭৫০ - ৪৫০০) = ১,২৫০$ টাকা।<br><br>
      <b>উত্তর:</b> ১,২৫০ টাকা।
    `
