    solution: `
      পরীক্ষার্থী পাস নম্বরের চেয়ে ৩৫ নম্বর কম পেয়ে ৩২৫ পেয়েছে।<br>
      $\\therefore$ পাস নম্বর = $(৩২৫ + ৩৫) = ৩৬০$<br><br>
      প্রশ্নমতে,<br>
      মোট নম্বরের ৪৫% = ৩৬০ নম্বর<br><br>
      ৪৫ নম্বর পাস হলে পূর্ণ নম্বর = ১০০ নম্বর<br>
      $\\therefore$ ১ নম্বর পাস হলে পূর্ণ নম্বর = $\\frac{১০০}{৪৫}$ নম্বর<br>
      $\\therefore$ ৩৬০ নম্বর পাস হলে পূর্ণ নম্বর = $\\frac{১০০ \\times ৩৬০}{৪৫} = ১০০ \\times ৮ = ৮০০$ নম্বর।<br><br>
      <b>উত্তর:</b> ৮০০ নম্বর।
    `
