    id: 101,
    chapterId: 15, // অধ্যায় ১৫: সরল ও মান নির্ণয়
    category: "সরল ও মান নির্ণয়",
    postType: "অফিস সহকারী কাম-কম্পিউটার মুদ্রাক্ষরিক",
    source: "জেলা ও দায়রা জজ আদালত, খুলনা",
    examYear: "২০২৪",
    question: "$x + y = 12$ এবং $xy = 27$ হলে, $(x - y)^2$ ও $x^2 + y^2$ এর মান নির্ণয় করুন।",
    solution: `
      দেওয়া আছে, $x + y = 12$ এবং $xy = 27$<br><br>
      ১ম রাশি $= (x - y)^2$<br>
      $= (x + y)^2 - 4xy$<br>
      $= (12)^2 - 4(27)$<br>
      $= 144 - 108$<br>
      $= 36$<br><br>
      ২য় রাশি $= x^2 + y^2$<br>
      $= (x + y)^2 - 2xy$<br>
      $= (12)^2 - 2(27)$<br>
      $= 144 - 54$<br>
      $= 90$<br><br>
      <b>উত্তর:</b> $(x - y)^2 = 36$ এবং $x^2 + y^2 = 90$
    `
