    chapterId: 15, // অধ্যায় ১৫: সরল ও মান নির্ণয়
    category: "সরল ও মান নির্ণয়",
    postType: "অফিস সহকারী কাম-কম্পিউটার মুদ্রাক্ষরিক",
    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "$x^2 - 3x + 1 = 0$ হলে, $x^2 - \\frac{1}{x^2}$ এর মান কত?",
    solution: `
      দেওয়া আছে, $x^2 - 3x + 1 = 0$<br>
      $\\Rightarrow x^2 + 1 = 3x$<br>
      $\\Rightarrow x + \\frac{1}{x} = 3$ [উভয়পক্ষকে $x$ দ্বারা ভাগ করে]<br><br>
      আমরা জানি,<br>
      $\\left(x - \\frac{1}{x}\\right)^2 = \\left(x + \\frac{1}{x}\\right)^2 - 4 \\cdot x \\cdot \\frac{1}{x}$<br>
      $= (3)^2 - 4 = 9 - 4 = 5$<br>
      $\\therefore x - \\frac{1}{x} = \\sqrt{5}$<br><br>
      এখন,<br>
      $x^2 - \\frac{1}{x^2} = \\left(x + \\frac{1}{x}\\right)\\left(x - \\frac{1}{x}\\right)$<br>
      $= 3 \\times \\sqrt{5}$<br>
      $= 3\\sqrt{5}$<br><br>
      <b>উত্তর:</b> $3\\sqrt{5}$
    `
