    solution: `
      দেওয়া আছে, $f(x) = x^3 + mx^2 - 3x - 6$<br><br>
      $\\therefore f(-3) = (-3)^3 + m(-3)^2 - 3(-3) - 6$<br>
      $= -27 + 9m + 9 - 6$<br>
      $= -24 + 9m$<br><br>
      প্রশ্নমতে,<br>
      $-24 + 9m = 3$<br>
      $\\Rightarrow 9m = 3 + 24$<br>
      $\\Rightarrow 9m = 27$<br>
      $\\Rightarrow m = \\frac{27}{9}$<br>
      $\\therefore m = 3$<br><br>
      <b>উত্তর:</b> 3
    `
