    solution: `
      ১ হালির ক্রয়মূল্য = ২৫ টাকা<br>
      $\\therefore$ ২ হালির ক্রয়মূল্য = $(২৫ \\times ২) = ৫০$ টাকা<br><br>
      ২ হালি ৫৬ টাকায় বিক্রয় করলে লাভ হয় = $(৫৬ - ৫০) = ৬$ টাকা<br><br>
      ৫০ টাকায় লাভ হয় ৬ টাকা<br>
      $\\therefore$ ১ টাকায় লাভ হয় = $\\frac{৬}{৫০}$ টাকা<br>
      $\\therefore$ ১০০ টাকায় লাভ হয় = $\\frac{৬ \\times ১০০}{৫০} = ১২$ টাকা<br><br>
      <b>উত্তর:</b> ১২% লাভ।
    `
