    question: "যদি $a + b = 3$ এবং $ab = 2$ হয় তবে $a^3 + b^3 = 9$ প্রমাণ কর।",
    solution: `
      দেওয়া আছে, $a + b = 3$ এবং $ab = 2$<br><br>
      বামপক্ষ $= a^3 + b^3$<br>
      $= (a + b)^3 - 3ab(a + b)$<br>
      $= (3)^3 - 3(2)(3)$<br>
      $= 27 - 18$<br>
      $= 9$<br>
      $= $ ডানপক্ষ<br><br>
      <b>(প্রমাণিত)</b>
    `
