    question: "$m + \\frac{1}{m} = 2$ হলে, প্রমাণ করুন যে, $m^4 + \\frac{1}{m^4} = 2$",
    solution: `
      দেওয়া আছে, $m + \\frac{1}{m} = 2$<br><br>
      উভয়পক্ষকে বর্গ করে পাই,<br>
      $\\left(m + \\frac{1}{m}\\right)^2 = (2)^2$<br>
      $\\Rightarrow m^2 + 2 \\cdot m \\cdot \\frac{1}{m} + \\frac{1}{m^2} = 4$<br>
      $\\Rightarrow m^2 + 2 + \\frac{1}{m^2} = 4$<br>
      $\\Rightarrow m^2 + \\frac{1}{m^2} = 4 - 2$<br>
      $\\Rightarrow m^2 + \\frac{1}{m^2} = 2$<br><br>
      পুনরায় উভয়পক্ষকে বর্গ করে পাই,<br>
      $\\left(m^2 + \\frac{1}{m^2}\\right)^2 = (2)^2$<br>
      $\\Rightarrow (m^2)^2 + 2 \\cdot m^2 \\cdot \\frac{1}{m^2} + \\left(\\frac{1}{m^2}\\right)^2 = 4$<br>
      $\\Rightarrow m^4 + 2 + \\frac{1}{m^4} = 4$<br>
      $\\Rightarrow m^4 + \\frac{1}{m^4} = 4 - 2$<br>
      $\\therefore m^4 + \\frac{1}{m^4} = 2$<br><br>
      <b>(প্রমাণিত)</b>
    `
