    question: "দুটি সংখ্যার গ.সা.গু. ও ল.সা.গু. যথাক্রমে ২ এবং ৩৬০। একটি সংখ্যা ১০ হলে, অপর সংখ্যাটি কত?",
    solution: `
      আমরা জানি,<br>
      দুটি সংখ্যার গুণফল = ল.সা.গু. $\\times$ গ.সা.গু.<br><br>
      প্রশ্নমতে,<br>
      ১০ $\\times$ অপর সংখ্যা = $২ \\times ৩৬০$<br>
      $\\Rightarrow$ অপর সংখ্যা = $\\frac{২ \\times ৩৬০}{১০}$<br>
      $\\therefore$ অপর সংখ্যা = ৭২<br><br>
      <b>উত্তর:</b> ৭২
    `
