    question: "একটি বৃত্তের পরিধি ও ব্যাসের অনুপাত কত?",
    solution: `
      ধরি, বৃত্তের ব্যাসার্ধ = $r$<br>
      $\\therefore$ বৃত্তের পরিধি = $2\\pi r$<br>
      এবং বৃত্তের ব্যাস = $2r$<br><br>
      $\\therefore$ বৃত্তের পরিধি ও ব্যাসের অনুপাত = $\\frac{2\\pi r}{2r} = \\pi = \\frac{22}{7}$ বা $২২ : ৭$।<br><br>
      <b>উত্তর:</b> $\\pi$ (বা $২২ : ৭$)।
    `
