    category: "সরল ও মান নির্ণয়",
    postType: "নিরাপত্তা প্রহরী",
    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "$x + y = 3$ হলে, $x^3 + y^3 + 9xy$ এর মান কত?",
    solution: `
      দেওয়া আছে, $x + y = 3$<br><br>
      প্রদত্ত রাশি $= x^3 + y^3 + 9xy$<br>
      $= (x + y)^3 - 3xy(x + y) + 9xy$<br>
      $= (3)^3 - 3xy(3) + 9xy$<br>
      $= 27 - 9xy + 9xy$<br>
      $= 27$<br><br>
      <b>উত্তর:</b> 27
    `
