    solution: `
      আলিফ ও খালিদ একত্রে ১ দিনে করে = $\\left(\\frac{১}{২০} + \\frac{১}{৩০}\\right) = \\frac{৩ + ২}{৬০} = \\frac{৫}{৬০} = \\frac{১}{১২}$ অংশ<br>
      $\\therefore$ একত্রে ৩ দিনে করে = $\\left(\\frac{১}{১২} \\times ৩\\right) = \\frac{১}{৪}$ অংশ<br><br>
      অবশিষ্ট কাজ = $১ - \\frac{১}{৪} = \\frac{৩}{৪}$ অংশ<br><br>
      খালিদ ১ অংশ করে ৩০ দিনে<br>
      $\\therefore$ খালিদ $\\frac{৩}{৪}$ অংশ করে = $\\left(৩০ \\times \\frac{৩}{৪}\\right) = \\frac{৪৫}{২} = ২২\\frac{১}{২}$ দিনে<br><br>
      $\\therefore$ কাজটি মোট শেষ হয়েছিল = $\\left(৩ + ২২\\frac{১}{২}\\right) = ২৫\\frac{১}{২}$ দিনে।<br><br>
      <b>উত্তর:</b> $২৫\\frac{১}{২}$ দিনে।
    `
