    solution: `
      দেওয়া আছে, $x + \\frac{1}{x} = 2$<br><br>
      উভয়পক্ষকে বর্গ করে পাই,<br>
      $\\left(x + \\frac{1}{x}\\right)^2 = 2^2$<br>
      $\\Rightarrow x^2 + 2 \\cdot x \\cdot \\frac{1}{x} + \\frac{1}{x^2} = 4$<br>
      $\\Rightarrow x^2 + \\frac{1}{x^2} = 4 - 2 = 2$<br><br>
      পুনরায় উভয়পক্ষকে বর্গ করে পাই,<br>
      $\\left(x^2 + \\frac{1}{x^2}\\right)^2 = 2^2$<br>
      $\\Rightarrow x^4 + 2 \\cdot x^2 \\cdot \\frac{1}{x^2} + \\frac{1}{x^4} = 4$<br>
      $\\Rightarrow x^4 + \\frac{1}{x^4} = 4 - 2 = 2$<br><br>
      <b>উত্তর:</b> 2
    `
