    examYear: "২০২৪",
    question: "সংজ্ঞা লিখুন: স্থূলকোণ, ত্রিভুজ, বিপ্রতীপ কোণ, জ্যা ও ট্রাপিজিয়াম।",
    solution: `
      <b>১. স্থূলকোণ (Obtuse Angle):</b> ৯০°-এর চেয়ে বড় কিন্তু ১৮০°-এর চেয়ে ছোট কোণকে স্থূলকোণ বলে। অর্থাৎ $১৮০° > x > ৯০°$ হলে $x$ একটি স্থূলকোণ।<br><br>
      <b>২. ত্রিভুজ (Triangle):</b> তিনটি সরলরেখা দ্বারা সীমাবদ্ধ ক্ষেত্রকে ত্রিভুজ বলে।<br><br>
      <b>৩. বিপ্রতীপ কোণ (Vertically Opposite Angle):</b> দুটি সরলরেখা পরস্পরকে ছেদ করলে ছেদবিন্দুতে যে চারটি কোণ উৎপন্ন হয়, তাদের যেকোনো একটি কোণকে তার বিপরীত পার্শ্বে অবস্থিত কোণের বিপ্রতীপ কোণ বলে। বিপ্রতীপ কোণদ্বয় পরস্পর সমান।<br><br>
      <b>৪. জ্যা (Chord):</b> বৃত্তের পরিধির যেকোনো দুটি বিন্দুর সংযোজক সরলরেখাকে জ্যা বলে। উল্লেখ্য, বৃত্তের ব্যাস হচ্ছে বৃত্তের বৃহত্তম জ্যা।<br><br>
      <b>৫. ট্রাপিজিয়াম (Trapezium):</b> যে চতুর্ভুজের কেবলমাত্র দুটি বিপরীত বাহু পরস্পর সমান্তরাল তাকে ট্রাপিজিয়াম বলে। এর ক্ষেত্রফল = $\\frac{১}{২} \\times (\\text{সমান্তরাল বাহুদ্বয়ের যোগফল}) \\times (\\text{তাদের মধ্যবর্তী লম্ব দূরত্ব})$।
    `
