    question: "১টি চৌবাচ্চার $\\frac{৩}{৫}$ অংশ পূরণ হতে ৭ ঘণ্টা সময় লাগে। চৌবাচ্চাটির বাকি অংশ পূরণ হতে আর কত সময় লাগবে?",
    solution: `
      সম্পূর্ণ চৌবাচ্চা = ১ অংশ<br>
      $\\therefore$ অবশিষ্ট বা বাকি অংশ = $\\left(১ - \\frac{৩}{৫}\\right) = \\frac{৫ - ৩}{৫} = \\frac{২}{৫}$ অংশ<br><br>
      $\\frac{৩}{৫}$ অংশ পূর্ণ হতে সময় লাগে ৭ ঘণ্টা<br>
      $\\therefore$ ১ (সম্পূর্ণ) অংশ পূর্ণ হতে সময় লাগে = $\\frac{৭ \\times ৫}{৩}$ ঘণ্টা<br>
      $\\therefore \\frac{২}{৫}$ অংশ পূর্ণ হতে সময় লাগে = $\\frac{৭ \\times ৫ \\times ২}{৩ \\times ৫} = \\frac{১৪}{৩} = ৪\\frac{২}{৩}$ ঘণ্টা (বা ৪ ঘণ্টা ৪০ মিনিট)।<br><br>
      <b>উত্তর:</b> $\\frac{১৪}{৩}$ ঘণ্টা বা $৪\\frac{২}{৩}$ ঘণ্টা।
    `
