    question: "$x^3 + \\frac{1}{x^3} = 18\\sqrt{3}$ হলে, প্রমাণ করুন যে, $x = \\sqrt{3} + \\sqrt{2}$",
    solution: `
      দেওয়া আছে, $x^3 + \\frac{1}{x^3} = 18\\sqrt{3}$<br><br>
      $\\Rightarrow \\frac{x^6 + 1}{x^3} = 18\\sqrt{3}$<br>
      $\\Rightarrow x^6 - 18\\sqrt{3}x^3 + 1 = 0$<br>
      $\\Rightarrow (x^3)^2 - 2 \\cdot x^3 \\cdot 9\\sqrt{3} + (9\\sqrt{3})^2 - (9\\sqrt{3})^2 + 1 = 0$<br>
      $\\Rightarrow (x^3 - 9\\sqrt{3})^2 - (243 - 1) = 0$<br>
      $\\Rightarrow (x^3 - 9\\sqrt{3})^2 = 242$<br>
      $\\Rightarrow x^3 - 9\\sqrt{3} = \\sqrt{242} = \\sqrt{121 \\times 2} = 11\\sqrt{2}$<br>
      $\\Rightarrow x^3 = 9\\sqrt{3} + 11\\sqrt{2}$<br>
      $= 3\\sqrt{3} + 9\\sqrt{2} + 6\\sqrt{3} + 2\\sqrt{2}$<br>
      $= (\\sqrt{3})^3 + 3 \\cdot (\\sqrt{3})^2 \\cdot \\sqrt{2} + 3 \\cdot \\sqrt{3} \\cdot (\\sqrt{2})^2 + (\\sqrt{2})^3$<br>
      $= (\\sqrt{3} + \\sqrt{2})^3$<br><br>
      উভয়পক্ষ থেকে ঘনমূল নিয়ে পাই,<br>
      $\\therefore x = \\sqrt{3} + \\sqrt{2}$<br><br>
      <b>(প্রমাণিত)</b>
    `
