    id: 172,
    chapterId: 9, // অধ্যায় ০৯: পরিমাপ (পরিমিতি)
    category: "পরিমাপ",
    postType: "অফিস সহকারী কাম-কম্পিউটার মুদ্রাক্ষরিক",
    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "একটি চৌবাচ্চার দৈর্ঘ্য ৩ মিটার, প্রস্থ ২ মিটার ও উচ্চতা ৪ মিটার। এতে কত লিটার এবং কত কিলোগ্রাম বিশুদ্ধ পানি ধরবে?",
    solution: `
      দেওয়া আছে,<br>
      চৌবাচ্চার দৈর্ঘ্য = ৩ মিটার = ৩০০ সে.মি.<br>
      চৌবাচ্চার প্রস্থ = ২ মিটার = ২০০ সে.মি.<br>
      চৌবাচ্চার উচ্চতা = ৪ মিটার = ৪০০ সে.মি.<br><br>
      $\\therefore$ চৌবাচ্চার আয়তন = $(৩০০ \\times ২০০ \\times ৪০০)$ ঘন সে.মি. $= ২৪,০০০,০০০$ ঘন সে.মি.<br><br>
      আমরা জানি,<br>
      ১০০০ ঘন সে.মি. = ১ লিটার<br>
      $\\therefore ২৪,০০০,০০০$ ঘন সে.মি. = $\\frac{২৪,০০০,০০০}{১০০০} = ২৪,০০০$ লিটার।<br><br>
      আবার,<br>
      ১ লিটার বিশুদ্ধ পানির ওজন = ১ কিলোগ্রাম<br>
      $\\therefore ২৪,০০০$ লিটার বিশুদ্ধ পানির ওজন = $(১ \\times ২৪,০০০) = ২৪,০০০$ কিলোগ্রাম।<br><br>
      <b>উত্তর:</b> ২৪,০০০ লিটার এবং ২৪,০০০ কিলোগ্রাম।
    `
