    question: "$3x^2 - x - 10$ এর উৎপাদক কত?",
    solution: `
      প্রদত্ত রাশি = $3x^2 - x - 10$<br>
      $= 3x^2 - 6x + 5x - 10$<br>
      $= 3x(x - 2) + 5(x - 2)$<br>
      $= (x - 2)(3x + 5)$<br><br>
      <b>উত্তর:</b> $(x - 2)(3x + 5)$
    `
