    solution: `
      ধরি,<br>
      ৫ বছর পূর্বে পুত্রের বয়স ছিল = $x$ বছর<br>
      $\\therefore$ ৫ বছর পূর্বে পিতার বয়স ছিল = $৫x$ বছর<br><br>
      বর্তমানে পুত্রের বয়স = $(x + ৫)$ বছর<br>
      এবং বর্তমানে পিতার বয়স = $(৫x + ৫)$ বছর<br><br>
      প্রশ্নমতে,<br>
      $(x + ৫) + (৫x + ৫) = ৪০$<br>
      $\\Rightarrow ৬x + ১০ = ৪০$<br>
      $\\Rightarrow ৬x = ৪০ - ১০$<br>
      $\\Rightarrow ৬x = ৩০$<br>
      $\\Rightarrow x = \\frac{৩০}{৬}$<br>
      $\\therefore x = ৫$<br><br>
      $\\therefore$ পুত্রের বর্তমান বয়স = $(৫ + ৫) = ১০$ বছর<br>
      এবং পিতার বর্তমান বয়স = $(৫ \\times ৫ + ৫) = ৩০$ বছর।<br><br>
      <b>উত্তর:</b> পিতার বর্তমান বয়স ৩০ বছর এবং পুত্রের বর্তমান বয়স ১০ বছর।
    `
