    solution: `
      প্রদত্ত রাশি = $x^2 - 3x - 28$<br>
      $= x^2 - 7x + 4x - 28$<br>
      $= x(x - 7) + 4(x - 7)$<br>
      $= (x - 7)(x + 4)$<br><br>
      <b>উত্তর:</b> $(x - 7)(x + 4)$
    `
