    question: "$2x + \\frac{2}{x} = 3$ হলে, $x^2 + \\frac{1}{x^2}$ এর মান কত?",
    solution: `
      দেওয়া আছে,<br>
      $2x + \\frac{2}{x} = 3$<br>
      $\\Rightarrow 2\\left(x + \\frac{1}{x}\\right) = 3$<br>
      $\\Rightarrow x + \\frac{1}{x} = \\frac{3}{2}$<br><br>
      এখন,<br>
      $x^2 + \\frac{1}{x^2} = \\left(x + \\frac{1}{x}\\right)^2 - 2 \\cdot x \\cdot \\frac{1}{x}$<br>
      $= \\left(\\frac{3}{2}\\right)^2 - 2$<br>
      $= \\frac{9}{4} - 2$<br>
      $= \\frac{9 - 8}{4} = \\frac{1}{4}$<br><br>
      <b>উত্তর:</b> $\\frac{1}{4}$
    `
