    question: "$2x - \\frac{2}{x} = 3$ হলে, প্রমাণ করুন যে, $8\\left(x^3 - \\frac{1}{x^3}\\right) = 63$",
    solution: `
      দেওয়া আছে,<br>
      $2x - \\frac{2}{x} = 3$<br>
      $\\Rightarrow 2\\left(x - \\frac{1}{x}\\right) = 3$<br>
      $\\Rightarrow x - \\frac{1}{x} = \\frac{3}{2}$<br><br>
      বামপক্ষ $= 8\\left(x^3 - \\frac{1}{x^3}\\right)$<br>
      $= 8\\left\\{\\left(x - \\frac{1}{x}\\right)^3 + 3 \\cdot x \\cdot \\frac{1}{x}\\left(x - \\frac{1}{x}\\right)\\right\\}$<br>
      $= 8\\left\\{\\left(\\frac{3}{2}\\right)^3 + 3\\left(\\frac{3}{2}\\right)\\right\\}$<br>
      $= 8\\left(\\frac{27}{8} + \\frac{9}{2}\\right)$<br>
      $= 8\\left(\\frac{27 + 36}{8}\\right)$<br>
      $= 8 \\times \\frac{63}{8}$<br>
      $= 63$ = ডানপক্ষ<br><br>
      <b>(প্রমাণিত)</b>
    `
