    question: "প্রমাণ করুন যে, কোনো ত্রিভুজের একটি বাহু অপর একটি বাহু অপেক্ষা বৃহত্তর হলে, বৃহত্তর বাহুর বিপরীত কোণ ক্ষুদ্রতর বাহুর বিপরীত কোণ অপেক্ষা বৃহত্তর হবে।",
    solution: `
      <b>বিশেষ নির্বচন:</b> মনে করি, $\\triangle ABC$-এ $AC > AB$। প্রমাণ করতে হবে যে, $\\angle ABC > \\angle ACB$।<br><br>
      <b>অঙ্কন:</b> $AC$ বাহু থেকে $AB$-এর সমান করে $AD$ অংশ কেটে নিই এবং $B, D$ যোগ করি।<br><br>
      <b>প্রমাণ:</b><br>
      ১. $\\triangle ABD$-এ $AD = AB$<br>
      $\\therefore \\angle ABD = \\angle ADB$ [যেহেতু সমদ্বিবাহু ত্রিভুজের ভূমি সংলগ্ন কোণদ্বয় সমান]<br><br>
      ২. কিন্তু $\\triangle BDC$-এর বহিঃস্থ কোণ $\\angle ADB > \\angle BCD$<br>
      $\\Rightarrow \\angle ABD > \\angle BCD$<br>
      বা, $\\angle ABD > \\angle ACB$<br><br>
      ৩. কিন্তু $\\angle ABC > \\angle ABD$ [কারণ $\\angle ABD$ হলো $\\angle ABC$-এর একটি অংশ]<br><br>
      $\\therefore \\angle ABC > \\angle ACB$<br><br>
      <b>(প্রমাণিত)</b>
    `
