    id: 221,
    chapterId: 17, // অধ্যায় ১৭: গ.সা.গু এবং ল.সা.গু
    category: "গ.সা.গু এবং ল.সা.গু",
    postType: "অফিস সহকারী কাম-কম্পিউটার মুদ্রাক্ষরিক",
