    solution: `
      দেওয়া আছে,<br>
      ১ কেজি সন্দেশের দাম = ২৫০ টাকা<br>
      $\\therefore$ ২ কেজি সন্দেশের দাম = $(২ \\times ২৫০) = ৫০০$ টাকা<br><br>
      ভ্যাটের হার ৪% (১০০ টাকায় ৪ টাকা):<br>
      ১০০ টাকায় ভ্যাট দিতে হয় ৪ টাকা<br>
      $\\therefore$ ১ টাকায় ভ্যাট দিতে হয় = $\\frac{৪}{১০০}$ টাকা<br>
      $\\therefore$ ৫০০ টাকায় ভ্যাট দিতে হয় = $\\frac{৪ \\times ৫০০}{১০০} = ২০$ টাকা<br><br>
      $\\therefore$ সন্দেশ ক্রয় বাবদ মোট দিতে হবে = $(৫০০ + ২০) = ৫২০$ টাকা।<br><br>
      <b>উত্তর:</b> ৫২০ টাকা।
    `
