    category: "উৎপাদক",
    postType: "নিরাপত্তা প্রহরী",
    source: "কর্ম কমিশন সচিবালয়",
    examYear: "২০২৪",
    question: "উৎপাদকে বিশ্লেষণ করুন: $25(a + 2b)^2 - 36(2a - 5b)^2$",
    solution: `
      প্রদত্ত রাশি = $25(a + 2b)^2 - 36(2a - 5b)^2$<br>
      $= \\{5(a + 2b)\\}^2 - \\{6(2a - 5b)\\}^2$<br>
      $= \\{5(a + 2b) + 6(2a - 5b)\\}\\{5(a + 2b) - 6(2a - 5b)\\}$<br>
      $= (5a + 10b + 12a - 30b)(5a + 10b - 12a + 30b)$<br>
      $= (17a - 20b)(40b - 7a)$ বা $(17a - 20b)(-7a + 40b)$<br><br>
      <b>উত্তর:</b> $(17a - 20b)(40b - 7a)$
    `
