    question: "লাবিব, সামি ও সিয়াম এর মধ্যে কিছু টাকা ৫ : ৪ : ২ অনুপাতে ভাগ করে দেওয়া হলো। সিয়াম ২০০ টাকা পেলে লাবিব কত টাকা পাবে?",
    solution: `
      দেওয়া আছে,<br>
      লাবিব : সামি : সিয়াম = ৫ : ৪ : ২<br><br>
      মনে করি,<br>
      লাবিব পায় = $৫x$ টাকা<br>
      সামি পায় = $৪x$ টাকা<br>
      এবং সিয়াম পায় = $২x$ টাকা<br><br>
      শর্তমতে,<br>
      $২x = ২০০$<br>
      $\\Rightarrow x = \\frac{২০০}{২}$<br>
      $\\therefore x = ১০০$<br><br>
      $\\therefore$ লাবিব পায় = $(৫ \\times ১০০) = ৫০০$ টাকা।<br><br>
      <b>উত্তর:</b> ৫০০ টাকা।
    `
