    solution: `
      দেওয়া আছে,<br>
      ক্রয়মূল্য = ১২০ টাকা এবং বিক্রয়মূল্য = ১৪৪ টাকা<br>
      $\\therefore$ লাভ = $(১৪৪ - ১২০) = ২৪$ টাকা<br><br>
      ১২০ টাকায় লাভ হয় ২৪ টাকা<br>
      $\\therefore$ ১ টাকায় লাভ হয় = $\\frac{২৪}{১২০}$ টাকা<br>
      $\\therefore$ ১০০ টাকায় লাভ হয় = $\\frac{২৪ \\times ১০০}{১২০} = ২০$ টাকা<br><br>
      <b>উত্তর:</b> ২০% লাভ।
    `
