    question: "১২০ মিটার দীর্ঘ একটি ট্রেন ৩৩০ মিটার দীর্ঘ একটি সেতু অতিক্রম করবে। ট্রেনটির গতিবেগ ঘণ্টায় ৪৫ কি.মি. হলে, সেতুটি অতিক্রম করতে ট্রেনটির কত সময় লাগবে?",
    solution: `
      সেতুটি অতিক্রম করতে ট্রেনটিকে তার নিজের দৈর্ঘ্য ও সেতুর দৈর্ঘ্য অতিক্রম করতে হবে।<br>
      $\\therefore$ মোট অতিক্রান্ত দূরত্ব = $(১২০ + ৩৩০) = ৪৫০$ মিটার<br><br>
      আমরা জানি,<br>
      ১ ঘণ্টা = ৩৬০০ সেকেন্ড<br>
      এবং ৪৫ কি.মি. = $(৪৫ \\times ১০০০) = ৪৫,০০০$ মিটার<br><br>
      ট্রেনটি ৪৫,০০০ মিটার যায় ৩৬০০ সেকেন্ডে<br>
      $\\therefore$ ১ মিটার যায় = $\\frac{৩৬০০}{৪৫,০০০}$ সেকেন্ডে<br>
      $\\therefore$ ৪৫০ মিটার যায় = $\\frac{৩৬০০ \\times ৪৫০}{৪৫,০০০} = ৩৬$ সেকেন্ডে।<br><br>
      <b>উত্তর:</b> ৩৬ সেকেন্ড।
    `
