    solution: `
      ক ও খ একত্রে ১০ দিনে করে কাজের ১ (সম্পূর্ণ) অংশ<br>
      $\\therefore$ ক ও খ একত্রে ১ দিনে করে কাজের = $\\frac{১}{১০}$ অংশ<br><br>
      আবার, ক একা ১৫ দিনে করে কাজের ১ অংশ<br>
      $\\therefore$ ক একা ১ দিনে করে কাজের = $\\frac{১}{১৫}$ অংশ<br><br>
      $\\therefore$ খ একা ১ দিনে করে = $\\left(\\frac{১}{১০} - \\frac{১}{১৫}\\right) = \\frac{৩ - ২}{৩০} = \\frac{১}{৩০}$ অংশ<br><br>
      খ একা $\\frac{১}{৩০}$ অংশ কাজ করে ১ দিনে<br>
      $\\therefore$ খ একা ১ (সম্পূর্ণ) অংশ কাজ করে = $(১ \\times ৩০) = ৩০$ দিনে।<br><br>
      <b>উত্তর:</b> ৩০ দিনে।
    `
