    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "$a - \\frac{1}{a} = 1$ হলে, $a^3 - \\frac{1}{a^3} =$ কত?",
    solution: `
      দেওয়া আছে, $a - \\frac{1}{a} = 1$<br><br>
      প্রদত্ত রাশি $= a^3 - \\frac{1}{a^3}$<br>
      $= \\left(a - \\frac{1}{a}\\right)^3 + 3 \\cdot a \\cdot \\frac{1}{a}\\left(a - \\frac{1}{a}\\right)$<br>
      $= (1)^3 + 3(1)$<br>
      $= 1 + 3$<br>
      $= 4$<br><br>
      <b>উত্তর:</b> 4
    `
