    question: "একজন ডিম বিক্রেতা প্রতি ডজন ডিম ১০১ টাকা দরে ৫ ডজন এবং ৯০ টাকা দরে ৬ ডজন ডিম কিনে কত টাকা দরে বিক্রয় করলে তার ডজন প্রতি ৩ টাকা লাভ হবে?",
