    postType: "অফিস সহায়ক",
    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "একটি আয়তক্ষেত্রের দৈর্ঘ্য ২৪ মিটার এবং প্রস্থ ১০ মিটার। ক্ষেত্রটির দৈর্ঘ্য ও প্রস্থ ৬% করে বৃদ্ধি করলে এর ক্ষেত্রফল শতকরা কত বাড়বে?",
    solution: `
      দেওয়া আছে,<br>
      আয়তক্ষেত্রের দৈর্ঘ্য = ২৪ মিটার এবং প্রস্থ = ১০ মিটার<br>
      $\\therefore$ আয়তক্ষেত্রের মূল ক্ষেত্রফল = $(২৪ \\times ১০) = ২৪০$ বর্গমিটার<br><br>
      ৬% বৃদ্ধিতে নতুন দৈর্ঘ্য = $২৪ + (২৪ \\text{ এর } ৬\\%)$ মিটার<br>
      $= ২৪ + \\left(২৪ \\times \\frac{৬}{১০০}\\right) = ২৪ + ১.৪৪ = ২৫.৪৪$ মিটার<br><br>
      এবং ৬% বৃদ্ধিতে নতুন প্রস্থ = $১০ + (১০ \\text{ এর } ৬\\%)$ মিটার<br>
      $= ১০ + \\left(১০ \\times \\frac{৬}{১০০}\\right) = ১০ + ০.৬ = ১০.৬$ মিটার<br><br>
      $\\therefore$ নতুন ক্ষেত্রফল = $(২৫.৪৪ \\times ১০.৬) = ২৬৯.৬৬৪$ বর্গমিটার<br><br>
      ক্ষেত্রফল বৃদ্ধি পায় = $(২৬৯.৬৬৪ - ২৪০) = ২৯.৬৬৪$ বর্গমিটার<br><br>
      $\\therefore$ ক্ষেত্রফল শতকরা বৃদ্ধি পায় = $\\left(\\frac{২৯.৬৬৪}{২৪০} \\times ১০০\\right)\\% = ১২.৩৬\\%$<br><br>
      <i>বিকল্প নিয়ম: $A + B + \\frac{AB}{১০০} = ৬ + ৬ + \\frac{৬ \\times ৬}{১০০} = ১২ + ০.৩৬ = ১২.৩৬\\%$</i><br><br>
      <b>উত্তর:</b> ১২.৩৬%
    `
