    solution: `
      দেওয়া আছে,<br>
      প্রতিশত কমলার ক্রয়মূল্য = ২০০০ টাকা<br>
      এবং প্রতিশত কমলার বিক্রয়মূল্য = ২৫০০ টাকা<br><br>
      যেহেতু বিক্রয়মূল্য ক্রয়মূল্যের চেয়ে বেশি, তাই লাভ হয়েছে।<br>
      $\\therefore$ লাভ = $(২৫০০ - ২০০০) = ৫০০$ টাকা<br><br>
      ২০০০ টাকায় লাভ হয় ৫০০ টাকা<br>
      $\\therefore$ ১ টাকায় লাভ হয় = $\\frac{৫০০}{২০০০}$ টাকা<br>
      $\\therefore$ ১০০ টাকায় লাভ হয় = $\\frac{৫০০ \\times ১০০}{২০০০} = ২৫$ টাকা<br><br>
      <b>উত্তর:</b> লাভ ২৫%।
    `
