    examYear: "২০২৪",
    question: "উৎপাদকে বিশ্লেষণ করুন: $x^4 - 6x^2 + 1$",
    solution: `
      প্রদত্ত রাশি = $x^4 - 6x^2 + 1$<br>
      $= (x^2)^2 - 2 \\cdot x^2 \\cdot 1 + (1)^2 - 4x^2$<br>
      $= (x^2 - 1)^2 - (2x)^2$<br>
      $= (x^2 - 1 + 2x)(x^2 - 1 - 2x)$<br>
      $= (x^2 + 2x - 1)(x^2 - 2x - 1)$<br><br>
      <b>উত্তর:</b> $(x^2 + 2x - 1)(x^2 - 2x - 1)$
    `
