    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "$a^6 + 5a^3 + 8$ কে উৎপাদকে বিশ্লেষণ কর।",
    solution: `
      প্রদত্ত রাশি = $a^6 + 5a^3 + 8$<br>
      $= a^6 + 8 - a^3 + 6a^3$<br>
      $= (a^2)^3 + (2)^3 + (-a)^3 - 3 \\cdot a^2 \\cdot 2 \\cdot (-a)$<br><br>
      আমরা জানি, $x^3 + y^3 + z^3 - 3xyz = (x + y + z)(x^2 + y^2 + z^2 - xy - yz - zx)$<br>
      এখানে, $x = a^2, y = 2, z = -a$<br><br>
      $= (a^2 + 2 - a)\\{(a^2)^2 + 2^2 + (-a)^2 - a^2 \\cdot 2 - 2(-a) - (-a)a^2\\}$<br>
      $= (a^2 - a + 2)(a^4 + 4 + a^2 - 2a^2 + 2a + a^3)$<br>
      $= (a^2 - a + 2)(a^4 + a^3 - a^2 + 2a + 4)$<br><br>
      <b>উত্তর:</b> $(a^2 - a + 2)(a^4 + a^3 - a^2 + 2a + 4)$
    `
