    chapterId: 7, // অধ্যায় ০৭: শতকরা হিসাব, লাভ-ক্ষতি (আয়কর)
    category: "শতকরা হিসাব, লাভ-ক্ষতি",
    postType: "অফিস সহকারী কাম-কম্পিউটার মুদ্রাক্ষরিক",
    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "মোস্তফা হাজরা এর মাসিক আয় ২৭,৬৫০ টাকা। তার বার্ষিক মোট আয়ের প্রথম ২,৫০,০০০ টাকার আয়কর ০ (শূন্য) টাকা। পরবর্তী টাকার উপর আয়করের হার ১০% হলে তিনি কত টাকা আয়কর প্রদান করবেন?",
    solution: `
      মোস্তফা হাজরা এর ১ মাসের আয় = ২৭,৬৫০ টাকা<br>
      $\\therefore$ ১ বছর বা ১২ মাসের আয় = $(২৭,৬৫০ \\times ১২) = ৩,৩১,৮০০$ টাকা<br><br>
      প্রথম ২,৫০,০০০ টাকা করমুক্ত হওয়ায়,<br>
      করযোগ্য আয় = $(৩,৩১,৮০০ - ২,৫০,০০০) = ৮১,৮০০$ টাকা<br><br>
      ১০% হারে প্রদেয় আয়করের পরিমাণ = ৮১,৮০০ এর ১০%<br>
      $= ৮১,৮০০ \\times \\frac{১০}{১০০} = ৮,১৮০$ টাকা।<br><br>
      <b>উত্তর:</b> ৮,১৮০ টাকা।
    `
