    solution: `
      ১০ কি.মি. যেতে পেট্রোল প্রয়োজন ১ লিটার<br>
      $\\therefore$ ১ কি.মি. যেতে পেট্রোল প্রয়োজন = $\\frac{১}{১০}$ লিটার<br>
      $\\therefore$ ১৭০ কি.মি. যেতে পেট্রোল প্রয়োজন = $\\frac{১ \\times ১৭০}{১০} = ১৭$ লিটার।<br><br>
      <b>উত্তর:</b> ১৭ লিটার।
    `
