    question: "সমাধান করুন: $\\frac{3x + 7}{4} + \\frac{5x - 4}{7} = x + 3\\frac{1}{2}$",
    solution: `
      প্রদত্ত সমীকরণ:<br>
      $\\frac{3x + 7}{4} + \\frac{5x - 4}{7} = x + 3\\frac{1}{2}$<br>
      $\\Rightarrow \\frac{3x + 7}{4} + \\frac{5x - 4}{7} - x = \\frac{7}{2}$<br>
      $\\Rightarrow \\frac{7(3x + 7) + 4(5x - 4) - 28x}{28} = \\frac{7}{2}$<br>
      $\\Rightarrow \\frac{21x + 49 + 20x - 16 - 28x}{28} = \\frac{7}{2}$<br>
      $\\Rightarrow \\frac{13x + 33}{28} = \\frac{7}{2}$<br>
      $\\Rightarrow 13x + 33 = \\frac{7 \\times 28}{2}$<br>
      $\\Rightarrow 13x + 33 = 98$<br>
      $\\Rightarrow 13x = 98 - 33$<br>
      $\\Rightarrow 13x = 65$<br>
      $\\therefore x = 5$<br><br>
      <b>উত্তর:</b> $x = 5$
    `
