    examYear: "২০২৫",
    question: "$a^3 - b^3 = 513$ এবং $a - b = 3$ হলে, $ab$ এর মান নির্ণয় করুন।",
    solution: `
      দেওয়া আছে, $a^3 - b^3 = 513$ এবং $a - b = 3$<br><br>
      আমরা জানি,<br>
      $a^3 - b^3 = (a - b)^3 + 3ab(a - b)$<br>
      $\\Rightarrow 513 = (3)^3 + 3ab(3)$<br>
      $\\Rightarrow 513 = 27 + 9ab$<br>
      $\\Rightarrow 9ab = 513 - 27$<br>
      $\\Rightarrow 9ab = 486$<br>
      $\\Rightarrow ab = \\frac{486}{9}$<br>
      $\\therefore ab = 54$<br><br>
      <b>উত্তর:</b> 54
    `
