    question: "$x^4 - x^2 + 1 = 0$ হলে, $x^3 + \\frac{1}{x^3}$ এর মান কত?",
    solution: `
      দেওয়া আছে, $x^4 - x^2 + 1 = 0$<br>
      $\\Rightarrow x^4 + 1 = x^2$<br>
      উভয়পক্ষকে $x^2$ দ্বারা ভাগ করে পাই,<br>
      $\\frac{x^4 + 1}{x^2} = 1$<br>
      $\\Rightarrow x^2 + \\frac{1}{x^2} = 1$<br>
      $\\Rightarrow \\left(x + \\frac{1}{x}\\right)^2 - 2 \\cdot x \\cdot \\frac{1}{x} = 1$<br>
      $\\Rightarrow \\left(x + \\frac{1}{x}\\right)^2 = 1 + 2 = 3$<br>
      $\\therefore x + \\frac{1}{x} = \\sqrt{3}$<br><br>
      প্রদত্ত রাশি $= x^3 + \\frac{1}{x^3}$<br>
      $= \\left(x + \\frac{1}{x}\\right)^3 - 3 \\cdot x \\cdot \\frac{1}{x}\\left(x + \\frac{1}{x}\\right)$<br>
      $= (\\sqrt{3})^3 - 3\\sqrt{3}$<br>
      $= 3\\sqrt{3} - 3\\sqrt{3}$<br>
      $= 0$<br><br>
      <b>উত্তর:</b> 0
    `
