    solution: `
      ১০টি লেবুর ক্রয়মূল্য ১ টাকা<br>
      $\\therefore$ ১টি লেবুর ক্রয়মূল্য = $\\frac{১}{১০}$ টাকা<br><br>
      ৮টি লেবুর বিক্রয়মূল্য ১ টাকা<br>
      $\\therefore$ ১টি লেবুর বিক্রয়মূল্য = $\\frac{১}{৮}$ টাকা<br><br>
      $\\therefore$ লাভ = $\\left(\\frac{১}{৮} - \\frac{১}{১০}\\right) = \\frac{৫ - ৪}{৪০} = \\frac{১}{৪০}$ টাকা<br><br>
      $\\frac{১}{১০}$ টাকায় লাভ হয় $\\frac{১}{৪০}$ টাকা<br>
      $\\therefore$ ১ টাকায় লাভ হয় = $\\frac{১}{৪০} \\times \\frac{১০}{১}$ টাকা<br>
      $\\therefore$ ১০০ টাকায় লাভ হয় = $\\frac{১ \\times ১০ \\times ১০০}{৪০} = ২৫$ টাকা<br><br>
      <b>উত্তর:</b> ২৫% লাভ।
    `
