    examYear: "২০২৫",
    question: "$a^2 - 2a + 1 = 0$ হলে, দেখান যে, $a^4 + \\frac{1}{a^4} = 2$",
    solution: `
      দেওয়া আছে, $a^2 - 2a + 1 = 0$<br>
      $\\Rightarrow a^2 + 1 = 2a$<br>
      উভয়পক্ষকে $a$ দ্বারা ভাগ করে পাই,<br>
      $\\frac{a^2 + 1}{a} = 2$<br>
      $\\Rightarrow a + \\frac{1}{a} = 2$<br><br>
      বামপক্ষ $= a^4 + \\frac{1}{a^4}$<br>
      $= (a^2)^2 + \\left(\\frac{1}{a^2}\\right)^2$<br>
      $= \\left(a^2 + \\frac{1}{a^2}\\right)^2 - 2 \\cdot a^2 \\cdot \\frac{1}{a^2}$<br>
      $= \\left\\{\\left(a + \\frac{1}{a}\\right)^2 - 2 \\cdot a \\cdot \\frac{1}{a}\\right\\}^2 - 2$<br>
      $= \\left\\{(2)^2 - 2\\right\\}^2 - 2$<br>
      $= (4 - 2)^2 - 2$<br>
      $= (2)^2 - 2$<br>
      $= 4 - 2 = 2$ = ডানপক্ষ<br><br>
      $\\therefore$ বামপক্ষ = ডানপক্ষ (দেখানো হলো)
    `
