    solution: `
      প্রদত্ত রাশি $= 25(x + y)^2 - 20(x + y)(y + z) + 4(y + z)^2$<br>
      $= \\{5(x + y)\\}^2 - 2 \\cdot 5(x + y) \\cdot 2(y + z) + \\{2(y + z)\\}^2$<br>
      $= [5(x + y) - 2(y + z)]^2$<br>
      $= (5x + 5y - 2y - 2z)^2$<br>
      $= (5x + 3y - 2z)^2$<br><br>
      এখন $x = 4, y = -8, z = 5$ মান বসিয়ে পাই,<br>
      $= \\{5(4) + 3(-8) - 2(5)\\}^2$<br>
      $= (20 - 24 - 10)^2$<br>
      $= (-14)^2$<br>
      $= 196$<br><br>
      <b>উত্তর:</b> 196
    `
