    solution: `
      মনে করি,<br>
      ১০ বছর পূর্বে পুত্রের বয়স ছিল $x$ বছর<br>
      এবং পিতার বয়স ছিল $4x$ বছর<br><br>
      $\\therefore$ পুত্রের বর্তমান বয়স = $(x + 10)$ বছর<br>
      এবং পিতার বর্তমান বয়স = $(4x + 10)$ বছর<br><br>
      ১০ বছর পরে,<br>
      পুত্রের বয়স হবে = $x + 10 + 10 = (x + 20)$ বছর<br>
      পিতার বয়স হবে = $4x + 10 + 10 = (4x + 20)$ বছর<br><br>
      শর্তমতে,<br>
      $\\frac{4x + 20}{x + 20} = \\frac{2}{1}$<br>
      $\\Rightarrow 4x + 20 = 2x + 40$<br>
      $\\Rightarrow 4x - 2x = 40 - 20$<br>
      $\\Rightarrow 2x = 20$<br>
      $\\therefore x = 10$<br><br>
      $\\therefore$ পিতার বর্তমান বয়স = $(4 \\times 10 + 10) = 50$ বছর<br>
      এবং পুত্রের বর্তমান বয়স = $(10 + 10) = 20$ বছর।<br><br>
      <b>উত্তর:</b> পিতার বর্তমান বয়স ৫০ বছর এবং পুত্রের বর্তমান বয়স ২০ বছর।
    `
