    question: "উৎপাদকে বিশ্লেষণ করুন: $x^3 + 6x^2y + 11xy^2 + 6y^3$",
    solution: `
      প্রদত্ত রাশি $= x^3 + 6x^2y + 11xy^2 + 6y^3$<br>
      $= x^3 + 6x^2y + 12xy^2 + 8y^3 - xy^2 - 2y^3$<br>
      $= (x + 2y)^3 - y^2(x + 2y)$<br>
      $= (x + 2y)\\{(x + 2y)^2 - y^2\\}$<br>
      $= (x + 2y)(x + 2y + y)(x + 2y - y)$<br>
      $= (x + 2y)(x + 3y)(x + y)$<br>
      $= (x + y)(x + 2y)(x + 3y)$<br><br>
      <b>উত্তর:</b> $(x + y)(x + 2y)(x + 3y)$
    `
