    source: "ধর্ম বিষয়ক মন্ত্রণালয়",
    examYear: "২০২৫",
    question: "একটি ট্রেন ২৫৪ মিটার দীর্ঘ একটি সেতুকে ২০ সেকেন্ডে এবং ১০০ মিটার দীর্ঘ অপর একটি সেতুকে ১৩ সেকেন্ডে অতিক্রম করল। ট্রেনটির দৈর্ঘ্য কত?",
    solution: `
      ধরি, ট্রেনটির দৈর্ঘ্য $x$ মিটার।<br><br>
      ট্রেনটি ২০ সেকেন্ডে অতিক্রম করে $(২৫৪ + x)$ মিটার<br>
      $\\therefore$ ট্রেনের গতিবেগ = $\\frac{২৫৪ + x}{২০}$ মি./সে.<br><br>
      আবার, ট্রেনটি ১৩ সেকেন্ডে অতিক্রম করে $(১০০ + x)$ মিটার<br>
      $\\therefore$ ট্রেনের গতিবেগ = $\\frac{১০০ + x}{১৩}$ মি./সে.<br><br>
      প্রশ্নমতে,<br>
      $\\frac{২৫৪ + x}{২০} = \\frac{১০০ + x}{১৩}$<br>
      $\\Rightarrow ২০(১০০ + x) = ১৩(২৫৪ + x)$<br>
      $\\Rightarrow ২০০০ + ২০x = ৩৩০২ + ১৩x$<br>
      $\\Rightarrow ২০x - ১৩x = ৩৩০২ - ২০০০$<br>
      $\\Rightarrow ৭x = ১৩০২$<br>
      $\\therefore x = \\frac{১৩০২}{৭} = ১৮৬$ মিটার।<br><br>
      <b>উত্তর:</b> ১৮৬ মিটার।
    `
