    question: "$a + b = 12$ এবং $ab = 35$ হলে, $a^2 + b^2$ এর মান নির্ণয় করুন।",
    solution: `
      দেওয়া আছে, $a + b = 12$ এবং $ab = 35$<br><br>
      প্রদত্ত রাশি $= a^2 + b^2$<br>
      $= (a + b)^2 - 2ab$<br>
      $= (12)^2 - 2(35)$<br>
      $= 144 - 70$<br>
      $= 74$<br><br>
      <b>উত্তর:</b> 74
    `
