    examYear: "২০২৫",
    question: "নাফিস ও তার মায়ের বয়সের সমষ্টি ৬০ বছর। মায়ের বয়স নাফিসের বয়সের ৪ গুণ। তাদের প্রত্যেকের বয়স কত?",
