    question: "সরল করুন: $3x - [5y - \\{10z - (5x - 10y + 3z)\\}]$",
    solution: `
      প্রদত্ত রাশি $= 3x - [5y - \\{10z - (5x - 10y + 3z)\\}]$<br>
      $= 3x - [5y - \\{10z - 5x + 10y - 3z\\}]$<br>
      $= 3x - [5y - \\{7z - 5x + 10y\\}]$<br>
      $= 3x - [5y - 7z + 5x - 10y]$<br>
      $= 3x - [-5y - 7z + 5x]$<br>
      $= 3x + 5y + 7z - 5x$<br>
      $= -2x + 5y + 7z$<br><br>
      <b>উত্তর:</b> $-2x + 5y + 7z$
    `
