    question: "'ক' একটি কাজ ১৫ দিনে, 'খ' তা ২০ দিনে এবং 'গ' ঐ কাজটি ১২ দিনে করতে পারে। তিন জন একত্রে ঐ কাজটি কত দিনে করতে পারবে?",
    solution: `
      ক ১ দিনে করে কাজের $\\frac{১}{১৫}$ অংশ<br>
      খ ১ দিনে করে কাজের $\\frac{১}{২০}$ অংশ<br>
      গ ১ দিনে করে কাজের $\\frac{১}{১২}$ অংশ<br><br>
      তারা একত্রে ১ দিনে করে = $\\left(\\frac{১}{১৫} + \\frac{১}{২০} + \\frac{১}{১২}\\right)$ অংশ<br>
      $= \\frac{৪ + ৩ + ৫}{৬০} = \\frac{১২}{৬০} = \\frac{১}{৫}$ অংশ<br><br>
      $\\frac{১}{৫}$ অংশ কাজ একত্রে করে ১ দিনে<br>
      $\\therefore$ সম্পূর্ণ (১ অংশ) কাজ একত্রে করে = $(১ \\times ৫) = ৫$ দিনে।<br><br>
      <b>উত্তর:</b> ৫ দিন।
    `
