    question: "সমাধান করুন: $\\frac{2}{2x - 1} + \\frac{3}{3x - 1} = \\frac{8}{4x + 1}$",
    solution: `
      প্রদত্ত সমীকরণ:<br>
      $\\frac{2}{2x - 1} + \\frac{3}{3x - 1} = \\frac{8}{4x + 1}$<br>
      $\\Rightarrow \\frac{2(3x - 1) + 3(2x - 1)}{(2x - 1)(3x - 1)} = \\frac{8}{4x + 1}$<br>
      $\\Rightarrow \\frac{6x - 2 + 6x - 3}{6x^2 - 5x + 1} = \\frac{8}{4x + 1}$<br>
      $\\Rightarrow \\frac{12x - 5}{6x^2 - 5x + 1} = \\frac{8}{4x + 1}$<br>
      $\\Rightarrow (12x - 5)(4x + 1) = 8(6x^2 - 5x + 1)$<br>
      $\\Rightarrow 48x^2 + 12x - 20x - 5 = 48x^2 - 40x + 8$<br>
      $\\Rightarrow -8x - 5 = -40x + 8$<br>
      $\\Rightarrow 40x - 8x = 8 + 5$<br>
      $\\Rightarrow 32x = 13$<br>
      $\\therefore x = \\frac{13}{32}$<br><br>
      <b>উত্তর:</b> $x = \\frac{13}{32}$
    `
