    id: 365,
    chapterId: 20, // অধ্যায় ২০: বৃত্ত (উপপাদ্য)
    category: "বৃত্ত",
    postType: "অফিস সহকারী কাম-কম্পিউটার মুদ্রাক্ষরিক",
    source: "বাংলাদেশ সুপ্রীম কোর্ট, হাইকোর্ট বিভাগ",
    examYear: "২০২৫",
    question: "প্রমাণ করুন যে, দুইটি বৃত্ত পরস্পর স্পর্শ করলে, তাদের কেন্দ্রদ্বয় ও স্পর্শ বিন্দু সমরেখ হবে।",
    solution: `
      <b>বিশেষ নির্বচন:</b> মনে করি, $A$ ও $B$ কেন্দ্রবিশিষ্ট দুইটি বৃত্ত পরস্পরকে $P$ বিন্দুতে বহিঃস্পর্শ করেছে। প্রমাণ করতে হবে যে, $A, P$ ও $B$ বিন্দু তিনটি সমরেখ।<br><br>
      <b>অঙ্কন:</b> $A, P$ এবং $B, P$ যোগ করি।<br><br>
      <b>প্রমাণ:</b> যেহেতু বৃত্তদ্বয় পরস্পরকে $P$ বিন্দুতে স্পর্শ করেছে, সুতরাং $P$ বিন্দুতে এদের একটি সাধারণ স্পর্শক বিদ্যমান।<br>
      ধরি, সাধারণ স্পর্শকটি $ST$।<br>
      এখন, $A$ কেন্দ্রবিশিষ্ট বৃত্তের $ST$ স্পর্শক এবং $AP$ স্পর্শবিন্দুগামী ব্যাসার্ধ।<br>
      $\\therefore AP \\perp ST$<br>
      অনুরূপভাবে, $B$ কেন্দ্রবিশিষ্ট বৃত্তের $ST$ স্পর্শক এবং $BP$ স্পর্শবিন্দুগামী ব্যাসার্ধ।<br>
      $\\therefore BP \\perp ST$<br><br>
      যেহেতু $AP$ ও $BP$ উভয়ই একই বিন্দু $P$-তে সাধারণ স্পর্শক $ST$-এর ওপর লম্ব, সেহেতু $AP$ ও $BP$ একই সরলরেখায় অবস্থিত।<br>
      অতএব, $A, P$ ও $B$ বিন্দু তিনটি সমরেখ। (প্রমাণিত)
    `
