    question: "আপনার মোবাইল ফোনের মাসিক বিল এসেছে ৪২০ টাকা। যদি এক বছর পর ১০% বৃদ্ধি পায় এবং আরো ৬ মাস পর ২০% বৃদ্ধি পায়, তাহলে ১৮ মাস পর আপনার বিল কত হবে?",
