    question: "$x^3 + y^3 = 9$ এবং $x + y = 3$ হলে, $xy$ এর মান কত?",
    solution: `
      আমরা জানি,<br>
      $x^3 + y^3 = (x + y)^3 - 3xy(x + y)$<br>
      $\\Rightarrow 9 = (3)^3 - 3xy(3)$<br>
      $\\Rightarrow 9 = 27 - 9xy$<br>
      $\\Rightarrow 9xy = 27 - 9$<br>
      $\\Rightarrow 9xy = 18$<br>
      $\\therefore xy = \\frac{18}{9} = 2$<br><br>
      <b>উত্তর:</b> 2
    `
