    category: "অনুপাত, মিশ্রণ ও বয়স",
    postType: "অফিস সহায়ক",
    source: "জাতীয় স্থানীয় সরকার ইনস্টিটিউট",
    examYear: "২০২৫",
    question: "ক ও খ এর আয়ের অনুপাত ৩ : ৪ এবং ব্যয়ের অনুপাত ৪ : ৫। যদি ক এর সঞ্চয় তার আয়ের ০.২৫ অংশ হয়, তবে তাদের সঞ্চয়ের অনুপাত নির্ণয় করুন।",
    solution: `
      মনে করি,<br>
      ক-এর আয় = $৩x$ এবং খ-এর আয় = $৪x$<br>
      ক-এর ব্যয় = $৪y$ এবং খ-এর ব্যয় = $৫y$<br><br>
      শর্তমতে, ক-এর সঞ্চয়:<br>
      $৩x - ৪y = ৩x \\times ০.২৫$<br>
      $\\Rightarrow ৩x - ৪y = \\frac{৩x}{৪}$<br>
      $\\Rightarrow ১২x - ১৬y = ৩x$<br>
      $\\Rightarrow ৯x = ১৬y$<br>
      $\\Rightarrow x = \\frac{১৬y}{৯}$<br><br>
      এখন, ক-এর সঞ্চয় = $৩x - ৪y = ৩\\left(\\frac{১৬y}{৯}\\right) - ৪y = \\frac{১৬y}{৩} - ৪y = \\frac{৪y}{৩}$<br><br>
      খ-এর সঞ্চয় = $৪x - ৫y = ৪\\left(\\frac{১৬y}{৯}\\right) - ৫y = \\frac{৬৪y}{৯} - ৫y = \\frac{১৯y}{৯}$<br><br>
      $\\therefore$ তাদের সঞ্চয়ের অনুপাত = $\\frac{৪y}{৩} : \\frac{১৯y}{৯} = \\left(\\frac{৪}{৩} \\times ৯\\right) : \\left(\\frac{১৯}{৯} \\times ৯\\right) = ১২ : ১৯$<br><br>
      <b>উত্তর:</b> ১২ : ১৯
    `
