    question: "একটি পুকুরের দৈর্ঘ্য ৩২ মিটার, প্রস্থ ২০ মিটার এবং পুকুরের পানির গভীরতা ৩ মিটার। একটি পানির মোটর দ্বারা পুকুরটি পানিশূন্য করা হচ্ছে যা প্রতি সেকেন্ডে ০.১ ঘনমিটার পানি সেচতে পারে। পুকুরটি পানিশূন্য করতে কত সময় লাগবে?",
    solution: `
      পুকুরটির মোট আয়তন = $(৩২ \\times ২০ \\times ৩) = ১৯২০$ ঘনমিটার<br><br>
      ০.১ ঘনমিটার পানি সেচে ১ সেকেন্ডে<br>
      $\\therefore$ ১৯২০ ঘনমিটার পানি সেচে = $\\frac{১৯২০}{০.১} = ১৯,২০০$ সেকেন্ডে<br><br>
      সময়কে ঘণ্টায় রূপান্তর করে পাই:<br>
      $\\frac{১৯,২০০}{৩৬০০} = ৫$ ঘণ্টা এবং অবশিষ্ট থাকে ১২০০ সেকেন্ড<br>
      $\\frac{১২০০}{৬০} = ২০$ মিনিট<br>
      $\\therefore$ মোট সময় লাগবে = ৫ ঘণ্টা ২০ মিনিট।<br><br>
      <b>উত্তর:</b> ৫ ঘণ্টা ২০ মিনিট।
    `
