    id: 415,
    chapterId: 7, // অধ্যায় ০৭: শতকরা হিসাব
    category: "শতকরা হিসাব, লাভ-ক্ষতি",
    postType: "নিরাপত্তা প্রহরী",
    source: "বাংলাদেশ লোক-প্রশাসন প্রশিক্ষণ কেন্দ্র (BPATC)",
    examYear: "২০২৫",
    question: "৮৮ এর ১২.৫ শতাংশ কত?",
    solution: `
      ৮৮ এর ১২.৫%<br>
      $= ৮৮ \\times \\frac{১২.৫}{১০০}$<br>
      $= ৮৮ \\times \\frac{১}{৮} = ১১$<br><br>
      <b>উত্তর:</b> ১১
    `
