    question: "$9x^2 - 36$ এর উৎপাদক কত?",
    solution: `
      প্রদত্ত রাশি $= 9x^2 - 36$<br>
      $= 9(x^2 - 4)$<br>
      $= 9(x^2 - 2^2)$<br>
      $= 9(x + 2)(x - 2)$<br><br>
      <b>উত্তর:</b> $9(x + 2)(x - 2)$
    `
