    examYear: "২০২৫",
    question: "যদি $m = 7 - 4\\sqrt{3}$ হয়, তবে $\\sqrt{m} + \\frac{1}{\\sqrt{m}}$ এর মান কত?",
    solution: `
      দেওয়া আছে, $m = 7 - 4\\sqrt{3}$<br>
      $\\therefore \\frac{1}{m} = \\frac{1}{7 - 4\\sqrt{3}} = \\frac{7 + 4\\sqrt{3}}{(7 - 4\\sqrt{3})(7 + 4\\sqrt{3})} = \\frac{7 + 4\\sqrt{3}}{49 - 48} = 7 + 4\\sqrt{3}$<br><br>
      $\\therefore m + \\frac{1}{m} = (7 - 4\\sqrt{3}) + (7 + 4\\sqrt{3}) = 14$<br><br>
      আমরা জানি,<br>
      $\\left(\\sqrt{m} + \\frac{1}{\\sqrt{m}}\\right)^2 = m + \\frac{1}{m} + 2 \\cdot \\sqrt{m} \\cdot \\frac{1}{\\sqrt{m}}$<br>
      $= 14 + 2 = 16$<br>
      $\\therefore \\sqrt{m} + \\frac{1}{\\sqrt{m}} = \\sqrt{16} = 4$<br><br>
      <b>উত্তর:</b> 4
    `
