    question: "দুটি সংখ্যার গুণফল ৪০ এবং ভাগফল $\\frac{৫}{২}$ হলে সংখ্যাদ্বয়ের যোগফল নির্ণয় করুন।",
    solution: `
      মনে করি, সংখ্যা দুটি $x$ এবং $y$<br>
      ১ম শর্তে, $xy = ৪০$ ............. (১)<br>
      ২য় শর্তে, $\\frac{x}{y} = \\frac{৫}{২} \\Rightarrow x = \\frac{৫y}{২}$<br><br>
      (১) নং সমীকরণে $x$-এর মান বসিয়ে পাই,<br>
      $\\frac{৫y}{২} \\times y = ৪০$<br>
      $\\Rightarrow ৫y^2 = ৮০$<br>
      $\\Rightarrow y^2 = ১৬$<br>
      $\\therefore y = ৪$<br><br>
      $\\therefore x = \\frac{৫ \\times ৪}{২} = ১০$<br><br>
      সংখ্যা দুটির যোগফল = $(১০ + ৪) = ১৪$<br><br>
      <b>উত্তর:</b> ১৪
    `
