    question: "একটি ক্লাসের শিক্ষার্থীদের মধ্যে ২,৭০০ চকলেট বিতরণ করা হলো। প্রত্যেক শিক্ষার্থী ক্লাসের মোট শিক্ষার্থীর সংখ্যার তিনগুণ চকলেট পেলে ক্লাসে মোট শিক্ষার্থী সংখ্যা কত?",
    solution: `
      মনে করি, মোট শিক্ষার্থী সংখ্যা = $x$ জন<br>
      $\\therefore$ প্রত্যেকে চকলেট পায় = $৩x$ টি<br><br>
      প্রশ্নমতে,<br>
      $x \\times ৩x = ২৭০০$<br>
      $\\Rightarrow ৩x^2 = ২৭০০$<br>
      $\\Rightarrow x^2 = ৯০০$<br>
      $\\therefore x = \\sqrt{৯০০} = ৩০$<br><br>
      <b>উত্তর:</b> ৩০ জন।
    `
