    examYear: "২০২৫",
    question: "উৎপাদকে বিশ্লেষণ করুন: $2x^2 - 3x - 35$",
    solution: `
      প্রদত্ত রাশি $= 2x^2 - 3x - 35$<br>
      $= 2x^2 - 10x + 7x - 35$<br>
      $= 2x(x - 5) + 7(x - 5)$<br>
      $= (x - 5)(2x + 7)$<br><br>
      <b>উত্তর:</b> $(x - 5)(2x + 7)$
    `
