    solution: `
      চাল বাবদ খরচ = $(৭ \\times ৬৪) = ৪৪৮$ টাকা<br>
      ডিম বাবদ খরচ = $(৫ \\times ৩৮) = ১৯০$ টাকা<br>
      তেল বাবদ খরচ = $(১৮০ \\div ২) = ৯০$ টাকা<br>
      মাছ বাবদ খরচ = $(৫৫০ \\div ২) = ২৭৫$ টাকা<br><br>
      $\\therefore$ মোট খরচ = $(৪৪৮ + ১৯০ + ৯০ + ২৭৫) = ১০০৩$ টাকা<br><br>
      $\\therefore$ অবশিষ্ট টাকা = $(১২০০ - ১০০৩) = ১৯৭$ টাকা।<br><br>
      <b>উত্তর:</b> ১৯৭ টাকা।
    `
