    solution: `
      প্রদত্ত রাশি $= 9x^2 - 9x - 4$<br>
      $= 9x^2 - 12x + 3x - 4$<br>
      $= 3x(3x - 4) + 1(3x - 4)$<br>
      $= (3x - 4)(3x + 1)$<br><br>
      <b>উত্তর:</b> $(3x - 4)(3x + 1)$
    `
