    question: "কোন কাজ রফিক ২০ দিনে এবং আতিক ৩০ দিনে করতে পারে। তারা একত্রে ৩ দিন কাজ করার পর বাকি কাজ আতিক একা সম্পন্ন করে। কাজটি কতদিনে শেষ হয়েছিল?",
    solution: `
      রফিক ও আতিক একত্রে ১ দিনে করে = $\\left(\\frac{১}{২০} + \\frac{১}{৩০}\\right) = \\frac{৩ + ২}{৬০} = \\frac{৫}{৬০} = \\frac{১}{১২}$ অংশ<br><br>
      $\\therefore$ তারা একত্রে ৩ দিনে করে = $\\frac{৩}{১২} = \\frac{১}{৪}$ অংশ<br><br>
      অবশিষ্ট কাজ থাকে = $\\left(১ - \\frac{১}{৪}\\right) = \\frac{৩}{৪}$ অংশ<br><br>
      আতিক ১ (সম্পূর্ণ) অংশ কাজ করে ৩০ দিনে<br>
      $\\therefore$ আতিক $\\frac{৩}{৪}$ অংশ কাজ করে = $৩০ \\times \\frac{৩}{৪} = \\frac{৪৫}{২} = ২২\\frac{১}{২}$ দিনে<br><br>
      $\\therefore$ সম্পূর্ণ কাজটি শেষ হতে মোট সময় লাগে = $৩ + ২২\\frac{১}{২} = ২৫\\frac{১}{২}$ দিন।<br><br>
      <b>উত্তর:</b> $২৫\\frac{১}{২}$ দিন।
    `
