    examYear: "২০২৫",
    question: "মান নির্ণয় করুন: (ক) $a + \\frac{1}{a} = 2$ হলে, $a^4 + \\frac{1}{a^4} =$ কত? (খ) $a = \\sqrt{3} - \\frac{1}{a}$ হলে, $a^3 + \\frac{1}{a^3} =$ কত?",
    solution: `
      (ক) দেওয়া আছে, $a + \\frac{1}{a} = 2$<br>
      $a^4 + \\frac{1}{a^4} = \\left(a^2 + \\frac{1}{a^2}\\right)^2 - 2$<br>
      $= \\left\\{\\left(a + \\frac{1}{a}\\right)^2 - 2\\right\\}^2 - 2$<br>
      $= \\{(2)^2 - 2\\}^2 - 2 = (4 - 2)^2 - 2 = 4 - 2 = 2$<br><br>
      (খ) দেওয়া আছে, $a = \\sqrt{3} - \\frac{1}{a} \\Rightarrow a + \\frac{1}{a} = \\sqrt{3}$<br>
      $a^3 + \\frac{1}{a^3} = \\left(a + \\frac{1}{a}\\right)^3 - 3\\left(a + \\frac{1}{a}\\right)$<br>
      $= (\\sqrt{3})^3 - 3\\sqrt{3} = 3\\sqrt{3} - 3\\sqrt{3} = 0$<br><br>
      <b>উত্তর:</b> (ক) 2 এবং (খ) 0
    `
