    question: "উৎপাদকে বিশ্লেষণ করুন: $2bd - a^2 - c^2 + b^2 + d^2 + 2ac$",
    solution: `
      প্রদত্ত রাশি $= 2bd - a^2 - c^2 + b^2 + d^2 + 2ac$<br>
      $= (b^2 + 2bd + d^2) - (a^2 - 2ac + c^2)$<br>
      $= (b + d)^2 - (a - c)^2$<br>
      $= \\{(b + d) + (a - c)\\}\\{(b + d) - (a - c)\\}$<br>
      $= (a + b - c + d)(b - a + c + d)$<br><br>
      <b>উত্তর:</b> $(a + b - c + d)(b - a + c + d)$
    `
