    solution: `
      মনে করি, প্রথম সংখ্যাটি $x$ এবং দ্বিতীয় সংখ্যাটি $y$<br><br>
      ১ম শর্তমতে, $3x + 2y = 59$ ............ (১)<br>
      ২য় শর্তমতে, $2x - y = 9$ .............. (২)<br><br>
      (২) নং সমীকরণকে ২ দ্বারা গুণ করে (১) নং সমীকরণের সাথে যোগ করে পাই,<br>
      $(3x + 2y) + (4x - 2y) = 59 + 18$<br>
      $\\Rightarrow 7x = 77$<br>
      $\\therefore x = 11$<br><br>
      $x$-এর মান (২) নং সমীকরণে বসিয়ে পাই,<br>
      $2(11) - y = 9$<br>
      $\\Rightarrow 22 - y = 9$<br>
      $\\therefore y = 22 - 9 = 13$<br><br>
      <b>উত্তর:</b> সংখ্যাদ্বয় যথাক্রমে ১১ এবং ১৩।
    `
