    examYear: "২০২৫",
    question: "জনাব রেজা তার সম্পদের ১২% স্ত্রীকে, ৫৮% ছেলেকে এবং অবশিষ্ট ৭,২০,০০০ টাকা মেয়েকে দিলেন। তার মোট সম্পদের মূল্য কত?",
    solution: `
      স্ত্রী ও ছেলে একত্রে পায় = $(১২\\% + ৫৮\\%) = ৭০\\%$<br>
      $\\therefore$ মেয়ের জন্য অবশিষ্ট থাকে = $(১০০ - ৭০)\\% = ৩০\\%$<br><br>
      শর্তমতে,<br>
      মোট সম্পদের ৩০% = ৭,২০,০০০ টাকা<br>
      $\\therefore$ মোট সম্পদের ১% = $\\frac{৭,২০,০০০}{৩০}$ টাকা<br>
      $\\therefore$ মোট সম্পদ (১০০%) = $\\frac{৭,২০,০০০ \\times ১০০}{৩০} = ২৪,০০,০০০$ টাকা।<br><br>
      <b>উত্তর:</b> ২৪,০০,০০০ টাকা।
    `
