    question: "খোকন ও মন্টুর আয়ের অনুপাত ৫ : ৪। খোকনের আয় ৮৫ টাকা হলে মন্টুর আয় কত?",
    solution: `
      দেওয়া আছে, $\\frac{\\text{খোকনের আয়}}{\\text{মন্টুর আয়}} = \\frac{৫}{৪}$<br><br>
      $\\Rightarrow \\frac{৮৫}{\\text{মন্টুর আয়}} = \\frac{৫}{৪}$<br>
      $\\Rightarrow \\text{মন্টুর আয়} = \\frac{৮৫ \\times ৪}{৫} = ১৭ \\times ৪ = ৬৮$ টাকা।<br><br>
      <b>উত্তর:</b> ৬৮ টাকা।
    `
