    solution: `
      প্রদত্ত রাশি $= x^2 + 14x + 45$<br>
      $= x^2 + 9x + 5x + 45$<br>
      $= x(x + 9) + 5(x + 9)$<br>
      $= (x + 9)(x + 5)$<br><br>
      <b>উত্তর:</b> $(x + 9)(x + 5)$
    `
