    solution: `
      মনে করি, প্রকৃত ভগ্নাংশটির লব = $x$<br>
      যেহেতু প্রকৃত ভগ্নাংশ, তাই হর লব অপেক্ষা বড় হবে।<br>
      $\\therefore$ হর = $(x + ১)$<br>
      $\\therefore$ ভগ্নাংশটি = $\\frac{x}{x + ১}$<br><br>
      প্রশ্নমতে,<br>
      $\\frac{x - ২}{(x + ১) + ২} = \\frac{২}{৭}$<br>
      $\\Rightarrow \\frac{x - ২}{x + ৩} = \\frac{২}{৭}$<br>
      $\\Rightarrow ৭(x - ২) = ২(x + ৩)$<br>
      $\\Rightarrow ৭x - ১৪ = ২x + ৬$<br>
      $\\Rightarrow ৭x - ২x = ৬ + ১৪$<br>
      $\\Rightarrow ৫x = ২০$<br>
      $\\therefore x = ৪$<br><br>
      $\\therefore$ হর = $(৪ + ১) = ৫$<br>
      $\\therefore$ নির্ণেয় ভগ্নাংশটি = $\\frac{৪}{৫}$<br><br>
      <b>উত্তর:</b> $\\frac{৪}{৫}$
    `
