    category: "বৃত্ত",
    postType: "অফিস সহায়ক",
    source: "বাংলাদেশ সেতু কর্তৃপক্ষ",
    examYear: "২০২৫",
    question: "একটি বৃত্তাকার মাঠের ব্যাস ১২৪ মিটার। মাঠের সীমানা ঘেঁষে ৬ মিটার চওড়া একটি রাস্তা আছে। রাস্তার ক্ষেত্রফল নির্ণয় করুন।",
    solution: `
      বৃত্তাকার মাঠের ব্যাসার্ধ, $r = \\frac{১২৪}{২} = ৬২$ মিটার<br>
      $\\therefore$ মাঠের ক্ষেত্রফল = $\\pi r^2 = ৩.১৪১৬ \\times (৬২)^2 \\approx ১২০৭৬.৩১$ বর্গমিটার<br><br>
      রাস্তাসহ মাঠের ব্যাসার্ধ, $R = ৬২ + ৬ = ৬৮$ মিটার<br>
      $\\therefore$ রাস্তাসহ মাঠের ক্ষেত্রফল = $\\pi R^2 = ৩.১৪১৬ \\times (৬৮)^2 \\approx ১৪৫২৬.৭৫$ বর্গমিটার<br><br>
      $\\therefore$ রাস্তার ক্ষেত্রফল = $(১৪৫২৬.৭৫ - ১২০৭৬.৩১) = ২৪৫০.৪৪$ বর্গমিটার।<br><br>
      <b>উত্তর:</b> ২৪৫০.৪৪ বর্গমিটার।
    `
