    id: 470,
    chapterId: 15, // অধ্যায় ১৫: সরল ও মান নির্ণয়
    category: "সরল ও মান নির্ণয়",
    postType: "অফিস সহায়ক",
    source: "কারিগরি শিক্ষা অধিদপ্তর",
    examYear: "২০২৫",
    question: "যদি $a^4 + a^2b^2 + b^4 = 3$ এবং $a^2 + ab + b^2 = 3$ হয়, তবে $a^2 + b^2$ এর মান কত?",
    solution: `
      আমরা জানি,<br>
      $a^4 + a^2b^2 + b^4 = (a^2 + ab + b^2)(a^2 - ab + b^2)$<br>
      $\\Rightarrow 3 = 3(a^2 - ab + b^2)$<br>
      $\\therefore a^2 - ab + b^2 = 1$ ............... (১)<br><br>
      দেওয়া আছে,<br>
      $a^2 + ab + b^2 = 3$ ....................... (২)<br><br>
      (১) ও (২) নং সমীকরণ যোগ করে পাই,<br>
      $2(a^2 + b^2) = 4$<br>
      $\\therefore a^2 + b^2 = \\frac{4}{2} = 2$<br><br>
      <b>উত্তর:</b> 2
    `
