    solution: `
      <b>সন্নিহিত কোণ:</b> যদি দুইটি কোণের একই শীর্ষবিন্দু হয় এবং তাদের একটি সাধারণ বাহু থাকে এবং কোণদ্বয় সাধারণ বাহুর বিপরীত পাশে অবস্থান করে, তবে কোণ দুটিকে সন্নিহিত কোণ বলে।<br><br>
      <b>সরল কোণ:</b> দুইটি বিপরীত রশ্মি তাদের সাধারণ প্রান্তবিন্দুতে যে কোণ উৎপন্ন করে, তাকে সরল কোণ বলে। এর পরিমাপ ১৮০° বা দুই সমকোণ।<br><br>
      <b>বিপ্রতীপ কোণ:</b> কোনো কোণের বাহুদ্বয়ের বিপরীত রশ্মিদ্বয় যে কোণ তৈরি করে, তাকে ঐ কোণের বিপ্রতীপ কোণ বলে। বিপ্রতীপ কোণদ্বয় পরস্পর সমান হয়।<br><br>
      <b>ব্যাস:</b> বৃত্তের কেন্দ্রগামী যেকোনো জ্যা-কে ব্যাস বলে। ব্যাস হলো বৃত্তের বৃহত্তম জ্যা।
    `
