    question: "$(4x - 5y)$ এর ঘন নির্ণয় করুন।",
    solution: `
      প্রদত্ত রাশি $= (4x - 5y)^3$<br>
      $= (4x)^3 - 3 \\cdot (4x)^2 \\cdot (5y) + 3 \\cdot (4x) \\cdot (5y)^2 - (5y)^3$<br>
      $= 64x^3 - 3 \\cdot (16x^2) \\cdot (5y) + 3 \\cdot (4x) \\cdot (25y^2) - 125y^3$<br>
      $= 64x^3 - 240x^2y + 300xy^2 - 125y^3$<br><br>
      <b>উত্তর:</b> $64x^3 - 240x^2y + 300xy^2 - 125y^3$
    `
