    id: 480,
    chapterId: 6, // অধ্যায় ০৬: সংখ্যার সমীকরণ
    category: "সংখ্যার সমীকরণ",
    postType: "নাজির কাম ক্যাশিয়ার",
    source: "জেলা প্রশাসকের কার্যালয়, জয়পুরহাট",
    examYear: "২০২৫",
    question: "দুই অঙ্কবিশিষ্ট কোনো সংখ্যার একক স্থানীয় অঙ্কটি দশক স্থানীয় অঙ্ক অপেক্ষা ২ বেশি। অঙ্কদ্বয় স্থান বিনিময় করলে যে সংখ্যা পাওয়া যাবে তা প্রদত্ত সংখ্যার দ্বিগুণ অপেক্ষা ৬ কম হবে। সংখ্যাটি নির্ণয় করুন।",
    solution: `
      মনে করি, দশক স্থানীয় অঙ্কটি = $x$<br>
      $\\therefore$ একক স্থানীয় অঙ্কটি = $x + 2$<br>
      $\\therefore$ সংখ্যাটি = $10x + (x + 2) = 11x + 2$<br><br>
      অঙ্কদ্বয় স্থান বিনিময় করলে পরিবর্তিত সংখ্যাটি হয়:<br>
      $= 10(x + 2) + x = 10x + 20 + x = 11x + 20$<br><br>
      প্রশ্নমতে,<br>
      $11x + 20 = 2(11x + 2) - 6$<br>
      $\\Rightarrow 11x + 20 = 22x + 4 - 6$<br>
      $\\Rightarrow 11x + 20 = 22x - 2$<br>
      $\\Rightarrow 22x - 11x = 20 + 2$<br>
      $\\Rightarrow 11x = 22$<br>
      $\\therefore x = 2$<br><br>
      $\\therefore$ সংখ্যাটি = $11(2) + 2 = 22 + 2 = 24$<br><br>
      <b>উত্তর:</b> 24
    `
