    examYear: "২০২৫",
    question: "কোন ক্ষুদ্রতম সংখ্যা হতে ১ বিয়োগ করলে বিয়োগফল ৯, ১২ ও ১৫ দ্বারা নিঃশেষে বিভাজ্য হবে?",
    solution: `
      প্রদত্ত সংখ্যাগুলোর ল.সা.গু নির্ণয় করি:<br>
      ৯, ১২, ১৫ এর ল.সা.গু = $৩ \\times ৩ \\times ৪ \\times ৫ = ১৮০$<br><br>
      যেহেতু সংখ্যাটি থেকে ১ বিয়োগ করলে তা নিঃশেষে বিভাজ্য হবে,<br>
      $\\therefore$ নির্ণেয় সংখ্যাটি = $১৮০ + ১ = ১৮১$<br><br>
      <b>উত্তর:</b> ১৮১
    `
