    chapterId: 12, // অধ্যায় ১২: ভগ্নাংশ ও পরিমাপ
    category: "ভগ্নাংশ ও দশমিক",
    postType: "সাঁটমুদ্রাক্ষরিক-কাম-কম্পিউটার অপারেটর",
    source: "কারিগরি শিক্ষা অধিদপ্তর",
    examYear: "২০২৫",
    question: "৫ ফুট দীর্ঘ ১টি তারকে এমনভাবে ২ ভাগ করা হলো যেন এক অংশ অন্য অংশের $\\frac{২}{৩}$। ছোট অংশটি কত ইঞ্চি?",
    solution: `
      আমরা জানি, ১ ফুট = ১২ ইঞ্চি<br>
      $\\therefore ৫$ ফুট = $(৫ \\times ১২) = ৬০$ ইঞ্চি<br><br>
      মনে করি, বড় অংশের দৈর্ঘ্য = $x$ ইঞ্চি<br>
      $\\therefore$ ছোট অংশের দৈর্ঘ্য = $\\frac{২x}{৩}$ ইঞ্চি<br><br>
      প্রশ্নমতে,<br>
      $x + \\frac{২x}{৩} = ৬০$<br>
      $\\Rightarrow \\frac{৩x + ২x}{৩} = ৬০$<br>
      $\\Rightarrow ৫x = ১৮০$<br>
      $\\therefore x = ৩৬$ ইঞ্চি<br><br>
      $\\therefore$ ছোট অংশটি = $\\frac{২ \\times ৩৬}{৩} = ২৪$ ইঞ্চি (বা ২ ফুট)।<br><br>
      <b>উত্তর:</b> ২৪ ইঞ্চি।
    `
