    id: 493,
    chapterId: 21, // অধ্যায় ২১: জ্যামিতি (পূরক কোণ)
    category: "জ্যামিতি",
    postType: "সাঁটমুদ্রাক্ষরিক-কাম-কম্পিউটার অপারেটর",
