    solution: `
      মনে করি, কোণটির মান = $x$<br>
      আমরা জানি, দুটি কোণের সমষ্টি $90^\\circ$ হলে তাদের পরস্পর পূরক কোণ বলে।<br>
      $\\therefore$ এর পূরক কোণ = $90^\\circ - x$<br><br>
      প্রশ্নমতে,<br>
      $x = \\frac{90^\\circ - x}{2}$<br>
      $\\Rightarrow 2x = 90^\\circ - x$<br>
      $\\Rightarrow 3x = 90^\\circ$<br>
      $\\therefore x = 30^\\circ$<br><br>
      <b>উত্তর:</b> $30^\\circ$
    `
