    id: 513,
    chapterId: 15, // অধ্যায় ১৫: সরল ও মান নির্ণয়
    category: "সরল ও মান নির্ণয়",
    postType: "সাঁটমুদ্রাক্ষরিক-কাম-কম্পিউটার অপারেটর",
    source: "প্রবাসী কল্যাণ ও বৈদেশিক কর্মসংস্থান মন্ত্রণালয়",
    examYear: "২০২৫",
    question: "যদি $\\left(a + \\frac{1}{a}\\right)^2 = 3$ হয়, তবে $a^3 + \\frac{1}{a^3}$ এর মান কত?",
    solution: `
      দেওয়া আছে, $\\left(a + \\frac{1}{a}\\right)^2 = 3$<br>
      $\\therefore a + \\frac{1}{a} = \\sqrt{3}$<br><br>
      প্রদত্ত রাশি $= a^3 + \\frac{1}{a^3}$<br>
      $= \\left(a + \\frac{1}{a}\\right)^3 - 3 \\cdot a \\cdot \\frac{1}{a}\\left(a + \\frac{1}{a}\\right)$<br>
      $= (\\sqrt{3})^3 - 3\\sqrt{3}$<br>
      $= 3\\sqrt{3} - 3\\sqrt{3}$<br>
      $= 0$<br><br>
      <b>উত্তর:</b> 0
    `
