    solution: `
      স্টেশন অতিক্রম করতে ট্রেনটির অতিক্রান্ত মোট দূরত্ব = $(৫০০ + ২৫০) = ৭৫০$ মিটার<br><br>
      ট্রেনের বেগ = ৩০ কি.মি./ঘণ্টা $= \\frac{৩০ \\times ১০০০}{৩৬০০}$ মি./সে. $= \\frac{২৫}{৩}$ মি./সে.<br><br>
      $\\therefore$ প্রয়োজনীয় সময় = $\\frac{\\text{দূরত্ব}}{\\text{বেগ}}$<br>
      $= \\frac{৭৫০}{\\frac{২৫}{৩}} = \\frac{৭৫০ \\times ৩}{২৫} = ৯০$ সেকেন্ড (বা ১ মিনিট ৩০ সেকেন্ড)।<br><br>
      <b>উত্তর:</b> ৯০ সেকেন্ড (বা ১ মিনিট ৩০ সেকেন্ড)।
    `
