    solution: `
      মনে করি, দ্রব্যটির ক্রয়মূল্য = $x$ টাকা।<br><br>
      ৩৭৮ টাকায় বিক্রয় করলে ক্ষতি হয় = $(x - ৩৭৮)$ টাকা<br>
      ৪৫০ টাকায় বিক্রয় করলে লাভ হয় = $(৪৫০ - x)$ টাকা<br><br>
      প্রশ্নমতে,<br>
      $৪৫০ - x = ৩(x - ৩৭৮)$<br>
      $\\Rightarrow ৪৫০ - x = ৩x - ১১৩৪$<br>
      $\\Rightarrow ৩x + x = ৪৫০ + ১১৩৪$<br>
      $\\Rightarrow ৪x = ১৫৮৪$<br>
      $\\therefore x = \\frac{১৫৮৪}{৪} = ৩৯৬$ টাকা।<br><br>
      <b>উত্তর:</b> ৩৯৬ টাকা।
    `
