    examYear: "২০২৫",
    question: "এক ব্যক্তি ২৫০০ টাকার একটি ঋণ কিছুসংখ্যক কিস্তিতে পরিশোধ করতে রাজি হন। প্রত্যেক কিস্তি পূর্বের কিস্তি থেকে ২ টাকা বেশি। যদি প্রথম কিস্তি ১ টাকা হয়, তবে কতগুলো কিস্তিতে ঐ ব্যক্তি তার ঋণ শোধ করতে পারবেন? এবং সর্বশেষ কিস্তির পরিমাণ কত হবে?",
    solution: `
      এখানে,<br>
      প্রথম পদ (প্রথম কিস্তি), $a = ১$<br>
      সাধারণ অন্তর, $d = ২$<br>
      সমষ্টি (মোট ঋণ), $S_n = ২৫০০$<br><br>
      আমরা জানি,<br>
      $S_n = \\frac{n}{2}\\{2a + (n - 1)d\\}$<br>
      $\\Rightarrow ২৫০০ = \\frac{n}{2}\\{2(1) + (n - 1)2\\}$<br>
      $\\Rightarrow ২৫০০ = \\frac{n}{2}(2 + 2n - 2)$<br>
      $\\Rightarrow ২৫০০ = \\frac{n}{2} \\times 2n$<br>
      $\\Rightarrow n^2 = ২৫০০$<br>
      $\\therefore n = \\sqrt{২৫০০} = ৫০$<br><br>
      $\\therefore$ মোট কিস্তির সংখ্যা = ৫০টি।<br><br>
      সর্বশেষ (৫০তম) কিস্তির পরিমাণ:<br>
      $= a + (n - 1)d$<br>
      $= ১ + (৫০ - ১)২ = ১ + (৪৯ \\times ২) = ১ + ৯৮ = ৯৯$ টাকা।<br><br>
      <b>উত্তর:</b> কিস্তির সংখ্যা ৫০টি এবং সর্বশেষ কিস্তির পরিমাণ ৯৯ টাকা।
    `
