    question: "যদি $a = \\sqrt{3} + \\sqrt{2}$ হয়, তবে প্রমাণ করুন যে, $a^3 + \\frac{1}{a^3} = 18\\sqrt{3}$।",
    solution: `
      দেওয়া আছে, $a = \\sqrt{3} + \\sqrt{2}$<br>
      $\\therefore \\frac{1}{a} = \\frac{1}{\\sqrt{3} + \\sqrt{2}} = \\frac{\\sqrt{3} - \n\sqrt{2}}{(\\sqrt{3} + \\sqrt{2})(\\sqrt{3} - \\sqrt{2})} = \\sqrt{3} - \\sqrt{2}$<br><br>
      $\\therefore a + \\frac{1}{a} = (\\sqrt{3} + \\sqrt{2}) + (\\sqrt{3} - \\sqrt{2}) = 2\\sqrt{3}$<br><br>
      L.H.S $= a^3 + \\frac{1}{a^3}$<br>
      $= \\left(a + \\frac{1}{a}\\right)^3 - 3 \\cdot a \\cdot \\frac{1}{a}\\left(a + \\frac{1}{a}\\right)$<br>
      $= (2\\sqrt{3})^3 - 3(2\\sqrt{3})$<br>
      $= 2^3 \\cdot (\\sqrt{3})^3 - 6\\sqrt{3}$<br>
      $= 8 \\times 3\\sqrt{3} - 6\\sqrt{3}$<br>
      $= 24\\sqrt{3} - 6\\sqrt{3} = 18\\sqrt{3}$ = R.H.S<br><br>
      $\\therefore a^3 + \\frac{1}{a^3} = 18\\sqrt{3}$ (প্রমাণিত)
    `
