    question: "এক বিক্রেতা ১০টি পেয়ারা যে দামে কিনে ৮টি পেয়ারা সেই দামে বিক্রয় করলে শতকরা কত লাভ বা ক্ষতি হবে?",
    solution: `
      মনে করি, ১০টি পেয়ারার ক্রয়মূল্য = ৮টি পেয়ারার বিক্রয়মূল্য = $x$ টাকা।<br><br>
      ১টি পেয়ারার ক্রয়মূল্য = $\\frac{x}{১০}$ টাকা<br>
      ১টি পেয়ারার বিক্রয়মূল্য = $\\frac{x}{৮}$ টাকা<br><br>
      $\\therefore$ লাভ = $\\frac{x}{৮} - \\frac{x}{১০} = \\frac{৫x - ৪x}{৪০} = \\frac{x}{৪০}$ টাকা<br><br>
      $\\frac{x}{১০}$ টাকায় লাভ হয় $\\frac{x}{৪০}$ টাকা<br>
      $\\therefore$ ১০০ টাকায় লাভ হয় = $\\frac{x \\times ১০ \\times ১০০}{৪০ \\times x} = ২৫$ টাকা।<br><br>
      <b>উত্তর:</b> ২৫% লাভ।
    `
