    id: 554,
    chapterId: 15, // অধ্যায় ১৫: বর্গের অন্তররূপে প্রকাশ
    category: "সরল ও মান নির্ণয়",
    postType: "অফিস সহায়ক",
    source: "জাতীয় জনসংখ্যা গবেষণা ও প্রশিক্ষণ ইনস্টিটিউট",
    examYear: "২০২৫",
    question: "$(x + 6)(x + 4)$ কে দুটি রাশির বর্গের অন্তররূপে প্রকাশ করুন।",
    solution: `
      ধরি, $a = x + 6$ এবং $b = x + 4$<br><br>
      আমরা জানি,<br>
      $ab = \\left(\\frac{a + b}{2}\\right)^2 - \\left(\\frac{a - b}{2}\\right)^2$<br>
      $= \\left(\\frac{x + 6 + x + 4}{2}\\right)^2 - \\left(\\frac{x + 6 - x - 4}{2}\\right)^2$<br>
      $= \\left(\\frac{2x + 10}{2}\\right)^2 - \\left(\\frac{2}{2}\\right)^2$<br>
      $= (x + 5)^2 - 1^2$<br><br>
      <b>উত্তর:</b> $(x + 5)^2 - 1^2$
    `
