    examYear: "২০২৫",
    question: "একটি হোস্টেলে ২০ জনের জন্য ৩০ দিনের খাবার মজুত ছিল। ১০ দিন পর ঐ হোস্টেল থেকে ৮ জন চলে গেল। তার ১০ দিন পর নতুন ২৩ জন যুক্ত হলে অবশিষ্ট খাবারে তাদের আর কত দিন চলবে?",
    solution: `
      ১ম ক্ষেত্রে (১০ দিন পর):<br>
      অবশিষ্ট দিন = $(৩০ - ১০) = ২০$ দিন<br>
      লোকসংখ্যা = $(২০ - ৮) = ১২$ জন<br><br>
      ২০ জনের খাবার চলে ২০ দিন<br>
      $\\therefore$ ১২ জনের খাবার চলবে = $\\frac{২০ \\times ২০}{১২} = \\frac{১০০}{৩}$ দিন<br><br>
      ২য় ক্ষেত্রে (আরও ১০ দিন পর):<br>
      ১২ জনের আর খাবার বাকি থাকে = $\\left(\\frac{১০০}{৩} - ১০\\right) = \\frac{৭০}{৩}$ দিনের<br>
      নতুন লোকসংখ্যা = $(১২ + ২৩) = ৩৫$ জন<br><br>
      ১২ জনের চলে $\\frac{৭০}{৩}$ দিন<br>
      $\\therefore$ ১ জনের চলে = $\\frac{৭০ \\times ১২}{৩}$ দিন<br>
      $\\therefore$ ৩৫ জনের চলবে = $\\frac{৭০ \\times ১২}{৩ \\times ৩৫} = ৮$ দিন।<br><br>
      <b>উত্তর:</b> ৮ দিন।
    `
