    question: "একটি মোটরসাইকেল ১৮০০ টাকায় বিক্রয় করাতে ১০% ক্ষতি হলো। কত টাকায় বিক্রয় করলে ১২% লাভ হবে?",
    solution: `
      ১০% ক্ষতিতে বিক্রয়মূল্য ৯০ টাকা হলে ক্রয়মূল্য ১০০ টাকা<br>
      $\\therefore$ বিক্রয়মূল্য ১৮০০ টাকা হলে ক্রয়মূল্য = $\\frac{১০০ \\times ১৮০০}{৯০} = ২০০০$ টাকা<br><br>
      ১২% লাভে,<br>
      ক্রয়মূল্য ১০০ টাকা হলে বিক্রয়মূল্য ১১২ টাকা<br>
      $\\therefore$ ক্রয়মূল্য ২০০০ টাকা হলে বিক্রয়মূল্য = $\\frac{১১২ \\times ২০০০}{১০০} = ২২৪০$ টাকা।<br><br>
      <b>উত্তর:</b> ২২৪০ টাকা।
    `
