    question: "$x - y = 3$ এবং $xy = 10$ হলে, $x^3 - y^3$ এর মান কত?",
    solution: `
      দেওয়া আছে, $x - y = 3$ এবং $xy = 10$<br><br>
      প্রদত্ত রাশি $= x^3 - y^3$<br>
      $= (x - y)^3 + 3xy(x - y)$<br>
      $= (3)^3 + 3(10)(3)$<br>
      $= 27 + 90$<br>
      $= 117$<br><br>
      <b>উত্তর:</b> 117
    `
