    postType: "অফিস সহায়ক",
    source: "প্রতিরক্ষা মন্ত্রণালয়",
    examYear: "২০২৫",
    question: "১০% কমিশনে একটি বই ক্রয় করে ১৮০ টাকা পরিশোধ করলে, বইটির প্রকৃত মূল্য কত টাকা ছিল?",
    solution: `
      ১০% কমিশনে বইয়ের পরিশোধিত মূল্য = $(১০০ - ১০) = ৯০$ টাকা<br><br>
      পরিশোধিত মূল্য ৯০ টাকা হলে প্রকৃত মূল্য ১০০ টাকা<br>
      $\\therefore$ পরিশোধিত মূল্য ১ টাকা হলে প্রকৃত মূল্য = $\\frac{১০০}{৯০}$ টাকা<br>
      $\\therefore$ পরিশোধিত মূল্য ১৮০ টাকা হলে প্রকৃত মূল্য = $\\frac{১০০ \\times ১৮০}{৯০} = ২০০$ টাকা।<br><br>
      <b>উত্তর:</b> ২০০ টাকা।
    `
