    question: "$x^2 - x - 20$ কে উৎপাদকে বিশ্লেষণ করুন।",
    solution: `
      প্রদত্ত রাশি $= x^2 - x - 20$<br>
      $= x^2 - 5x + 4x - 20$<br>
      $= x(x - 5) + 4(x - 5)$<br>
      $= (x - 5)(x + 4)$<br><br>
      <b>উত্তর:</b> $(x - 5)(x + 4)$
    `
