    solution: `
      প্রদত্ত রাশি $= (2a^2 + 2b - c^2)^2$<br>
      $= \\{(2a^2 + 2b) - c^2\\}^2$<br>
      $= (2a^2 + 2b)^2 - 2(2a^2 + 2b)c^2 + (c^2)^2$<br>
      $= (2a^2)^2 + 2(2a^2)(2b) + (2b)^2 - 4a^2c^2 - 4bc^2 + c^4$<br>
      $= 4a^4 + 8a^2b + 4b^2 - 4a^2c^2 - 4bc^2 + c^4$<br><br>
      <b>উত্তর:</b> $4a^4 + 8a^2b + 4b^2 - 4a^2c^2 - 4bc^2 + c^4$
    `
