    question: "$a^2 + \\frac{1}{a^2} = 5$ হলে, $a + \\frac{1}{a}$ এর মান কত?",
    solution: `
      আমরা জানি,<br>
      $\\left(a + \\frac{1}{a}\\right)^2 = a^2 + \\frac{1}{a^2} + 2$<br>
      $= 5 + 2 = 7$<br><br>
      $\\therefore a + \\frac{1}{a} = \\pm\\sqrt{7}$<br><br>
      <b>উত্তর:</b> $\\pm\\sqrt{7}$
    `
