    solution: `
      প্রদত্ত রাশি $= \\frac{17}{4} \\div \\left\\{\\frac{3}{4} - \\frac{1}{3}\\left(\\frac{4 + 1}{6}\\right)\\right\\}$<br>
      $= \\frac{17}{4} \\div \\left\\{\\frac{3}{4} - \\frac{1}{3} \\times \\frac{5}{6}\\right\\}$<br>
      $= \\frac{17}{4} \\div \\left\\{\\frac{3}{4} - \\frac{5}{18}\\right\\}$<br>
      $= \\frac{17}{4} \\div \\left\\{\\frac{27 - 10}{36}\\right\\}$<br>
      $= \\frac{17}{4} \\div \\frac{17}{36}$<br>
      $= \\frac{17}{4} \\times \\frac{36}{17} = 9$<br><br>
      <b>উত্তর:</b> 9
    `
