    solution: `
      ১ বছরের মোট বেতন = $(৪৩,১৭০ \\times ১২) = ৫,১৮,০৪০$ টাকা<br><br>
      করমুক্ত আয় = ২,৫০,০০০ টাকা<br>
      $\\therefore$ করযোগ্য আয় = $(৫,১৮,০৪০ - ২,৫০,০০০) = ২,৬৮,০৪০$ টাকা<br><br>
      $\\therefore$ প্রদেয় আয়কর = ২,৬৮,০৪০ এর ১০%<br>
      $= ২,৬৮,০৪০ \\times \\frac{১০}{১০০} = ২৬,৮০৪$ টাকা।<br><br>
      <b>উত্তর:</b> ২৬,৮০৪ টাকা।
    `
