    examYear: "২০২৫",
    question: "যদি $x - \\frac{1}{x} = 3$ হয়, তবে (ক) $\\left(x + \\frac{1}{x}\\right)^2$ এর মান কত? (খ) দেখাও যে, $x^4 = 119 - \\frac{1}{x^4}$।",
    solution: `
      দেওয়া আছে, $x - \\frac{1}{x} = 3$<br><br>
      (ক) আমরা জানি,<br>
      $\\left(x + \\frac{1}{x}\\right)^2 = \\left(x - \\frac{1}{x}\\right)^2 + 4 \\cdot x \\cdot \\frac{1}{x}$<br>
      $= 3^2 + 4 = 9 + 4 = 13$<br><br>
      (খ) দেওয়া আছে, $x - \\frac{1}{x} = 3$<br>
      উভয়পক্ষকে বর্গ করে পাই,<br>
      $\\left(x - \\frac{1}{x}\\right)^2 = 3^2$<br>
      $\\Rightarrow x^2 - 2 + \\frac{1}{x^2} = 9$<br>
      $\\Rightarrow x^2 + \\frac{1}{x^2} = 11$<br>
      পুনরায় বর্গ করে পাই,<br>
      $\\left(x^2 + \\frac{1}{x^2}\\right)^2 = 11^2$<br>
      $\\Rightarrow x^4 + 2 + \\frac{1}{x^4} = 121$<br>
      $\\Rightarrow x^4 + \\frac{1}{x^4} = 119$<br>
      $\\therefore x^4 = 119 - \\frac{1}{x^4}$ (দেখানো হলো)।<br><br>
      <b>উত্তর:</b> (ক) 13
    `
