    question: "যদি $x = 9 + 4\\sqrt{5}$ হয়, তবে $\\left(\\sqrt{x} - \\frac{1}{\\sqrt{x}}\\right)^2$ এর মান কত?",
    solution: `
      দেওয়া আছে, $x = 9 + 4\\sqrt{5}$<br>
      $\\therefore \\frac{1}{x} = \\frac{1}{9 + 4\\sqrt{5}} = \\frac{9 - 4\\sqrt{5}}{(9 + 4\\sqrt{5})(9 - 4\\sqrt{5})} = \\frac{9 - 4\\sqrt{5}}{81 - 80} = 9 - 4\\sqrt{5}$<br><br>
      $\\therefore x + \\frac{1}{x} = (9 + 4\\sqrt{5}) + (9 - 4\\sqrt{5}) = 18$<br><br>
      প্রদত্ত রাশি $= \\left(\\sqrt{x} - \\frac{1}{\\sqrt{x}}\\right)^2$<br>
      $= (\\sqrt{x})^2 - 2 \\cdot \\sqrt{x} \\cdot \\frac{1}{\\sqrt{x}} + \\left(\\frac{1}{\\sqrt{x}}\\right)^2$<br>
      $= x - 2 + \\frac{1}{x}$<br>
      $= \\left(x + \\frac{1}{x}\\right) - 2$<br>
      $= 18 - 2 = 16$<br><br>
      <b>উত্তর:</b> 16
    `
