    question: "পুত্রের বয়স মাতার বয়সের এক-তৃতীয়াংশ। পিতা মাতার চেয়ে ৬ বছরের বড়। তিনজনের বয়সের সমষ্টি ৯০ বছর। পিতার বয়স কত?",
    solution: `
      মনে করি, মাতার বয়স = $৩x$ বছর<br>
      $\\therefore$ পুত্রের বয়স = $\\frac{১}{৩} \\times ৩x = x$ বছর<br>
      $\\therefore$ পিতার বয়স = $(৩x + ৬)$ বছর<br><br>
      প্রশ্নমতে,<br>
      $x + ৩x + (৩x + ৬) = ৯০$<br>
      $\\Rightarrow ৭x + ৬ = ৯০$<br>
      $\\Rightarrow ৭x = ৮৪$<br>
      $\\therefore x = ১২$<br><br>
      $\\therefore$ পিতার বয়স = $(৩ \\times ১২ + ৬) = ৩৬ + ৬ = ৪২$ বছর।<br><br>
      <b>উত্তর:</b> ৪২ বছর।
    `
