    solution: `
      প্রদত্ত রাশি $= \\frac{a}{(a - b)(a - c)} + \\frac{b}{(b - c)(b - a)} + \\frac{c}{(c - a)(c - b)}$<br><br>
      চক্র-ক্রমিক আকারে হরগুলো সাজিয়ে পাই:<br>
      $= -\\frac{a}{(a - b)(c - a)} - \\frac{b}{(b - c)(a - b)} - \\frac{c}{(c - a)(b - c)}$<br>
      $= -\\left[ \\frac{a(b - c) + b(c - a) + c(a - b)}{(a - b)(b - c)(c - a)} \\right]$<br>
      $= -\\left[ \\frac{ab - ac + bc - ab + ca - bc}{(a - b)(b - c)(c - a)} \\right]$<br>
      $= -\\left[ \\frac{0}{(a - b)(b - c)(c - a)} \\right] = 0$<br><br>
      <b>উত্তর:</b> 0
    `
