    question: "সমাধান করুন: $2^{x + 7} = 4^{x + 2}$",
    solution: `
      প্রদত্ত সমীকরণ:<br>
      $2^{x + 7} = 4^{x + 2}$<br>
      $\\Rightarrow 2^{x + 7} = (2^2)^{x + 2}$<br>
      $\\Rightarrow 2^{x + 7} = 2^{2x + 4}$<br><br>
      ভিত্তি সমান হওয়ায় সূচকদ্বয় সমান হবে:<br>
      $x + 7 = 2x + 4$<br>
      $\\Rightarrow 2x - x = 7 - 4$<br>
      $\\therefore x = 3$<br><br>
      <b>উত্তর:</b> 3
    `
