    question: "$x + \\frac{1}{x} = 5$ হলে, $\\frac{x}{x^2 + x + 1}$ এর মান নির্ণয় করুন।",
    solution: `
      দেওয়া আছে, $x + \\frac{1}{x} = 5$<br>
      $\\Rightarrow \\frac{x^2 + 1}{x} = 5$<br>
      $\\therefore x^2 + 1 = 5x$<br><br>
      প্রদত্ত রাশি $= \\frac{x}{x^2 + x + 1}$<br>
      $= \\frac{x}{(x^2 + 1) + x}$<br>
      $= \\frac{x}{5x + x}$<br>
      $= \\frac{x}{6x} = \\frac{1}{6}$<br><br>
      <b>উত্তর:</b> $\\frac{1}{6}$
    `
