    solution: `
      মনে করি, ক্রয়মূল্য ১০০ টাকা<br><br>
      ৮% ক্ষতিতে বিক্রয়মূল্য = $(১০০ - ৮) = ৯২$ টাকা<br>
      ৮% লাভে বিক্রয়মূল্য = $(১০০ + ৮) = ১০৮$ টাকা<br><br>
      বিক্রয়মূল্যের পার্থক্য = $(১০৮ - ৯২) = ১৬$ টাকা<br><br>
      পার্থক্য ১৬ টাকা হলে ক্রয়মূল্য ১০০ টাকা<br>
      $\\therefore$ পার্থক্য ৪০০ টাকা হলে ক্রয়মূল্য = $\\frac{১০০ \\times ৪০০}{১৬} = ২৫০০$ টাকা।<br><br>
      <b>উত্তর:</b> ২৫০০ টাকা।
    `
