    question: "প্রতিদিন ৯ ঘণ্টা কাজ করে ১০ জন লোক একটি বর্গাকৃতি জমির ধান ২ দিনে কাটতে পারে। উক্ত জমির ধান ১ দিনে ১২ ঘণ্টা কাজ করে শেষ করতে অতিরিক্ত কতজন লোক লাগবে?",
    solution: `
      ১ম ক্ষেত্রে, মোট সময় = $(২ \\times ৯) = ১৮$ ঘণ্টা<br>
      ২য় ক্ষেত্রে, মোট সময় = $(১ \\times ১২) = ১২$ ঘণ্টা<br><br>
      ১৮ ঘণ্টার কাজে প্রয়োজন হয় ১০ জন লোক<br>
      $\\therefore$ ১ ঘণ্টার কাজে প্রয়োজন হয় = $(১০ \\times ১৮)$ জন লোক<br>
      $\\therefore$ ১২ ঘণ্টার কাজে প্রয়োজন হবে = $\\frac{১০ \\times ১৮}{১২} = ১৫$ জন লোক<br><br>
      $\\therefore$ অতিরিক্ত লোক লাগবে = $(১৫ - ১০) = ৫$ জন।<br><br>
      <b>উত্তর:</b> ৫ জন।
    `
