    category: "মুনাফা আসল",
    postType: "প্রধান সহকারী",
    source: "বাংলাদেশ কৃষি গবেষণা কাউন্সিল",
    examYear: "২০২৫",
    question: "জেমি ও সুমি একই ব্যাংক থেকে একই দিনে ১০% সরল সুদে আলাদা আলাদা পরিমাণ অর্থ ঋণ নেয়। জেমি ২ বছর পর সুদে-আসলে যত টাকা শোধ করে, ৩ বছর পর সুমি সুদে-আসলে তত টাকা শোধ করে। তাদের ঋণের অনুপাত নির্ণয় করুন।",
    solution: `
      মনে করি, জেমির মূলধন = $P_1$ টাকা এবং সুমির মূলধন = $P_2$ টাকা। সুদের হার $r = ১০\\% = 0.1$<br><br>
      জেমির ক্ষেত্রে ২ বছরের সুদ-আসল:<br>
      $A_1 = P_1(1 + nr) = P_1(1 + ২ \\times 0.1) = 1.2P_1$<br><br>
      সুমির ক্ষেত্রে ৩ বছরের সুদ-আসল:<br>
      $A_2 = P_2(1 + nr) = P_2(1 + ৩ \\times 0.1) = 1.3P_2$<br><br>
      প্রশ্নমতে,<br>
      $1.2P_1 = 1.3P_2$<br>
      $\\Rightarrow \\frac{P_1}{P_2} = \\frac{1.3}{1.2} = \\frac{১৩}{১২}$<br><br>
      $\\therefore P_1 : P_2 = ১৩ : ১২$<br><br>
      <b>উত্তর:</b> ১৩ : ১২
    `
