    examYear: "২০২৫",
    question: "একটি বইয়ের দৈর্ঘ্য ২৪ সে.মি. এবং প্রস্থ ১৮ সে.মি.। ঐ বইয়ের পরিসীমা সে.মি. ও মিটারে প্রকাশ করুন।",
    solution: `
      দেওয়া আছে, বইয়ের দৈর্ঘ্য = ২৪ সে.মি. এবং প্রস্থ = ১৮ সে.মি.<br><br>
      $\\therefore$ পরিসীমা = $২(\\text{দৈর্ঘ্য} + \\text{প্রস্থ})$<br>
      $= ২(২৪ + ১৮) = ২ \\times ৪২ = ৮৪$ সে.মি.<br><br>
      মিটারে রূপান্তর করে পাই:<br>
      $\\frac{৮৪}{১০০} = ০.৮৪$ মিটার।<br><br>
      <b>উত্তর:</b> ৮৪ সে.মি. বা ০.৮৪ মিটার।
    `
