    solution: `
      দেওয়ালের পুরুত্ব = ১৫ সে.মি. = ০.১৫ মিটার<br>
      উচ্চতা = ৩ মিটার<br><br>
      বাইরের দৈর্ঘ্য = $৪ + ২(০.১৫) = ৪.৩$ মিটার<br>
      বাইরের প্রস্থ = $৩.৫ + ২(০.১৫) = ৩.৮$ মিটার<br><br>
      চার দেওয়ালসহ ঘরের মোট আয়তন = $৪.৩ \\times ৩.৮ \\times ৩ = ৪৯.০২$ ঘনমিটার<br>
      ঘরের ভেতরের ফাঁকা অংশের আয়তন = $৪ \\times ৩.৫ \\times ৩ = ৪২$ ঘনমিটার<br><br>
      $\\therefore$ চার দেওয়ালের আয়তন = $(৪৯.০২ - ৪২) = ৭.০২$ ঘনমিটার।<br><br>
      <b>উত্তর:</b> ৭.০২ ঘনমিটার।
    `
