    solution: `
      মনে করি, ক্রয়মূল্য = ১০০ টাকা<br><br>
      ১২% ক্ষতিতে বিক্রয়মূল্য = $(১০০ - ১২) = ৮৮$ টাকা<br>
      ৮% লাভে বিক্রয়মূল্য = $(১০০ + ৮) = ১০৮$ টাকা<br><br>
      বিক্রয়মূল্যের পার্থক্য = $(১০৮ - ৮৮) = ২০$ টাকা<br><br>
      পার্থক্য ২০ টাকা হলে ক্রয়মূল্য ১০০ টাকা<br>
      $\\therefore$ পার্থক্য ১ টাকা হলে ক্রয়মূল্য = $\\frac{১০০}{২০}$ টাকা<br>
      $\\therefore$ পার্থক্য ১২০০ টাকা হলে ক্রয়মূল্য = $\\frac{১০০ \\times ১২০০}{২০} = ৬০০০$ টাকা।<br><br>
      <b>উত্তর:</b> ৬০০০ টাকা।
    `
