    id: 671,
    chapterId: 15, // অধ্যায় ১৫: সরল ও মান নির্ণয়
    category: "সরল ও মান নির্ণয়",
    postType: "বেঞ্চ সহকারী",
    source: "জাতীয় আইনগত সহায়তা প্রদান সংস্থা",
    examYear: "২০২৫",
    question: "$a + b = 7$ এবং $ab = 10$ হলে, $a^2 + b^2 + 3ab$ এর মান কত?",
    solution: `
      প্রদত্ত রাশি $= a^2 + b^2 + 3ab$<br>
      $= (a + b)^2 - 2ab + 3ab$<br>
      $= (a + b)^2 + ab$<br><br>
      মান বসিয়ে পাই:<br>
      $= (7)^2 + 10$<br>
      $= 49 + 10 = 59$<br><br>
      <b>উত্তর:</b> 59
    `
