    chapterId: 5, // অধ্যায় ০৫: অংশীদারি কারবার ও লভ্যাংশ বণ্টন
    category: "অনুপাত, মিশ্রণ ও বয়স",
    postType: "অফিস সহকারী কাম-কম্পিউটার মুদ্রাক্ষরিক",
    source: "জাতীয় আইনগত সহায়তা প্রদান সংস্থা",
    examYear: "২০২৫",
    question: "সুমন ও জামাল ৫০০০ টাকা ও ৪০০০ টাকা মূলধন নিয়ে একটি কারবার শুরু করল। ৩ মাস পর সুমন আরও ১০০০ টাকা দিল এবং কামাল ৭০০০ টাকা মূলধন নিয়ে কারবারে নতুন অংশীদার হলো। এক বছরে ৩৬,০০০ টাকা লাভ হলে, লাভের টাকা কে কত পাবে?",
    solution: `
      ১ মাস হিসেবে মূলধনের আনুপাতিক হিসাব:<br>
      সুমনের মোট মূলধন = $(৫০০০ \\times ৩) + (৬০০০ \\times ৯) = ১৫,০০০ + ৫৪,০০০ = ৬৯,০০০$ টাকা<br>
      জামালের মোট মূলধন = $৪০০০ \\times ১২ = ৪৮,০০০$ টাকা<br>
      কামালের মোট মূলধন = $৭০০০ \\times ৯ = ৬৩,০০০$ টাকা<br><br>
      মূলধনের অনুপাত = ৬৯,০০০ : ৪৮,০০০ : ৬৩,০০০ = ৬৯ : ৪৮ : ৬৩<br>
      অনুপাতের রাশিগুলোর যোগফল = $৬৯ + ৪৮ + ৬৩ = ১৮০$<br><br>
      মোট লাভ = ৩৬,০০০ টাকা<br>
      $\\therefore$ সুমন পাবে = $৩৬,০০০ \\times \\frac{৬৯}{১৮০} = ১৩,৮০০$ টাকা<br>
      $\\therefore$ জামাল পাবে = $৩৬,০০০ \\times \\frac{৪৮}{১৮০} = ৯,৬০০$ টাকা<br>
      $\\therefore$ কামাল পাবে = $৩৬,০০০ \\times \\frac{৬৩}{১৮০} = ১২,৬০০$ টাকা।<br><br>
      <b>উত্তর:</b> সুমন পাবে ১৩,৮০০ টাকা, জামাল পাবে ৯,৬০০ টাকা এবং কামাল পাবে ১২,৬০০ টাকা।
    `
