    chapterId: 15, // অধ্যায় ১৫: সরল ও বর্গের অন্তররূপে প্রকাশ
    category: "সরল ও মান নির্ণয়",
    postType: "অফিস সহকারী কাম-কম্পিউটার মুদ্রাক্ষরিক",
    source: "ইসলামিক ফাউন্ডেশন",
    examYear: "২০২৫",
    question: "$(2x + 3y)(4x - 5y)$ কে দুইটি বর্গের বিয়োগফলরূপে প্রকাশ করুন।",
    solution: `
      ধরি, $a = 2x + 3y$ এবং $b = 4x - 5y$<br><br>
      আমরা জানি,<br>
      $ab = \\left(\\frac{a + b}{2}\\right)^2 - \\left(\\frac{a - b}{2}\\right)^2$<br>
      $= \\left(\\frac{2x + 3y + 4x - 5y}{2}\\right)^2 - \\left(\\frac{2x + 3y - (4x - 5y)}{2}\\right)^2$<br>
      $= \\left(\\frac{6x - 2y}{2}\\right)^2 - \\left(\\frac{2x + 3y - 4x + 5y}{2}\\right)^2$<br>
      $= \\left(\\frac{2(3x - y)}{2}\\right)^2 - \\left(\\frac{8y - 2x}{2}\\right)^2$<br>
      $= \\left(\\frac{2(3x - y)}{2}\\right)^2 - \\left(\\frac{2(4y - x)}{2}\\right)^2$<br>
      $= (3x - y)^2 - (4y - x)^2$<br><br>
      <b>উত্তর:</b> $(3x - y)^2 - (4y - x)^2$
    `
