    question: "$a + b + c = 2$ এবং $ab + bc + ac = 1$ হলে, $(a + b)^2 + (b + c)^2 + (c + a)^2$ এর মান কত?",
    solution: `
      প্রদত্ত রাশি $= (a + b)^2 + (b + c)^2 + (c + a)^2$<br>
      $= a^2 + 2ab + b^2 + b^2 + 2bc + c^2 + c^2 + 2ca + a^2$<br>
      $= 2(a^2 + b^2 + c^2) + 2(ab + bc + ca)$<br><br>
      আমরা জানি,<br>
      $a^2 + b^2 + c^2 = (a + b + c)^2 - 2(ab + bc + ca)$<br>
      $= (2)^2 - 2(1) = 4 - 2 = 2$<br><br>
      $\\therefore$ প্রদত্ত রাশি $= 2(2) + 2(1) = 4 + 2 = 6$<br><br>
      <b>উত্তর:</b> 6
    `
