    question: "$x + y + 4 = x - y - 12 = 0$ হলে, $2x + y$ এর মান কত?",
    solution: `
      প্রদত্ত সমীকরণদ্বয়:<br>
      $x + y + 4 = 0 \\Rightarrow x + y = -4$ ................ (১)<br>
      $x - y - 12 = 0 \\Rightarrow x - y = 12$ ................ (২)<br><br>
      (১) ও (২) নং সমীকরণ যোগ করে পাই,<br>
      $2x = 8 \\Rightarrow x = 4$<br><br>
      $x$-এর মান (১) নং সমীকরণে বসিয়ে পাই,<br>
      $4 + y = -4 \\Rightarrow y = -4 - 4 = -8$<br><br>
      $\\therefore 2x + y = 2(4) + (-8) = 8 - 8 = 0$<br><br>
      <b>উত্তর:</b> 0
    `
