    source: "প্রাথমিক শিক্ষা অধিদপ্তর",
    examYear: "২০২৫",
    question: "সমকোণী ত্রিভুজের সমকোণ সংলগ্ন বাহুদ্বয় যথাক্রমে ৩ ও ৪ সেন্টিমিটার হলে এর অতিভুজের মান বের করুন।",
    solution: `
      দেওয়া আছে, ভূমি = ৪ সে.মি. এবং লম্ব = ৩ সে.মি.<br><br>
      পিথাগোরাসের উপপাদ্য অনুযায়ী,<br>
      $\\text{অতিভুজ}^২ = \\text{ভূমি}^২ + \\text{লম্ব}^২$<br>
      $\\Rightarrow \\text{অতিভুজ}^২ = ৪^২ + ৩^২$<br>
      $\\Rightarrow \\text{অতিভুজ}^২ = ১৬ + ৯ = ২৫$<br>
      $\\therefore \\text{অতিভুজ} = \\sqrt{২৫} = ৫$ সেন্টিমিটার।<br><br>
      <b>উত্তর:</b> ৫ সেন্টিমিটার।
    `
