    question: "যদি $x + \\frac{1}{x} = 5$ হয়, তবে $x^2 + \\frac{1}{x^2}$ এর মান কত?",
    solution: `
      দেওয়া আছে, $x + \\frac{1}{x} = 5$<br><br>
      প্রদত্ত রাশি $= x^2 + \\frac{1}{x^2}$<br>
      $= \\left(x + \\frac{1}{x}\\right)^2 - 2 \\cdot x \\cdot \\frac{1}{x}$<br>
      $= (5)^2 - 2$<br>
      $= 25 - 2 = 23$<br><br>
      <b>উত্তর:</b> 23
    `
