    chapterId: 8, // অধ্যায় ০৮: মুনাফা আসল (মিশ্র বিনিয়োগ)
    category: "মুনাফা আসল",
    postType: "বাংলাদেশ নৌবাহিনীর আর্টিস্ট",
    source: "প্রতিরক্ষা মন্ত্রণালয়",
    examYear: "২০২৫",
    question: "রাজু সাহেব তার ৫৬,০০০ টাকার কিছু টাকা বার্ষিক ১২% মুনাফায় ও বাকি টাকা বার্ষিক ১০% মুনাফায় বিনিয়োগ করলেন। এক বছর পর তিনি মোট ৬৪০০ টাকা মুনাফা পেলেন। তিনি ১২% মুনাফায় কত টাকা বিনিয়োগ করেছিলেন?",
    solution: `
      মনে করি, তিনি ১২% মুনাফায় বিনিয়োগ করেন $x$ টাকা<br>
      $\\therefore$ ১০% মুনাফায় বিনিয়োগ করেন $(৫৬,০০০ - x)$ টাকা<br><br>
      প্রশ্নমতে,<br>
      $\\frac{x \\times ১২ \\times ১}{১০০} + \\frac{(৫৬,০০০ - x) \\times ১০ \\times ১}{১০০} = ৬৪০০$<br>
      $\\Rightarrow ১২x + ৫,৬০,০০০ - ১০x = ৬,৪০,০০০$<br>
      $\\Rightarrow ২x = ৬,৪০,০০০ - ৫,৬০,০০০$<br>
      $\\Rightarrow ২x = ৮০,০০০$<br>
      $\\therefore x = ৪০,০০০$ টাকা।<br><br>
      <b>উত্তর:</b> ৪০,০০০ টাকা।
    `
