    category: "সংখ্যার সমীকরণ",
    postType: "বাংলাদেশ নৌবাহিনীর আর্টিস্ট",
    source: "প্রতিরক্ষা মন্ত্রণালয়",
    examYear: "২০২৫",
    question: "সমাধান করুন: $\\frac{6x + 1}{15} - \\frac{2x - 4}{7x - 1} = \\frac{2x - 1}{5}$",
    solution: `
      প্রদত্ত সমীকরণ:<br>
      $\\frac{6x + 1}{15} - \\frac{2x - 1}{5} = \\frac{2x - 4}{7x - 1}$<br>
      $\\Rightarrow \\frac{(6x + 1) - 3(2x - 1)}{15} = \\frac{2x - 4}{7x - 1}$<br>
      $\\Rightarrow \\frac{6x + 1 - 6x + 3}{15} = \\frac{2x - 4}{7x - 1}$<br>
      $\\Rightarrow \\frac{4}{15} = \\frac{2x - 4}{7x - 1}$<br><br>
      আড়গুণন করে পাই:<br>
      $4(7x - 1) = 15(2x - 4)$<br>
      $\\Rightarrow 28x - 4 = 30x - 60$<br>
      $\\Rightarrow 30x - 28x = 60 - 4$<br>
      $\\Rightarrow 2x = 56$<br>
      $\\therefore x = 28$<br><br>
      <b>উত্তর:</b> 28
    `
