    category: "জ্যামিতি",
    postType: "অফিস সহকারী কাম-কম্পিউটার মুদ্রাক্ষরিক",
    source: "ঢাকা মেডিকেল কলেজ হাসপাতাল",
    examYear: "২০২৫",
    question: "একটি সমবাহু ত্রিভুজের প্রত্যেক বাহুর দৈর্ঘ্য ১ মিটার বাড়ালে ক্ষেত্রফল $3\\sqrt{3}$ বর্গমিটার বেড়ে যায়। ত্রিভুজটির বাহুর দৈর্ঘ্য নির্ণয় করুন।",
    solution: `
      মনে করি, সমবাহু ত্রিভুজের বাহুর দৈর্ঘ্য = $a$ মিটার<br>
      $\\therefore$ ক্ষেত্রফল = $\\frac{\\sqrt{3}}{4}a^2$ বর্গমিটার<br><br>
      বাহুর দৈর্ঘ্য ১ মিটার বৃদ্ধি পেলে ক্ষেত্রফল হয় = $\\frac{\\sqrt{3}}{4}(a + 1)^2$ বর্গমিটার<br><br>
      প্রশ্নমতে,<br>
      $\\frac{\\sqrt{3}}{4}(a + 1)^2 - \\frac{\\sqrt{3}}{4}a^2 = 3\\sqrt{3}$<br>
      উভয়পক্ষকে $\\frac{\\sqrt{3}}{4}$ দ্বারা ভাগ করে পাই,<br>
      $(a + 1)^2 - a^2 = 12$<br>
      $\\Rightarrow a^2 + 2a + 1 - a^2 = 12$<br>
      $\\Rightarrow 2a = 11$<br>
      $\\therefore a = 5.5$ মিটার।<br><br>
      <b>উত্তর:</b> ৫.৫ মিটার।
    `
