    solution: `
      এখানে, ১ম পদ $a = 7$<br>
      সাধারণ অন্তর $d = 12 - 7 = 5$<br>
      পদসংখ্যা $n = 30$<br><br>
      আমরা জানি, সমান্তর ধারার প্রথম $n$ পদের সমষ্টি:<br>
      $S_n = \\frac{n}{2}\\{2a + (n - 1)d\\}$<br>
      $\\therefore S_{30} = \\frac{30}{2}\\{2(7) + (30 - 1)5\\}$<br>
      $= 15\\{14 + 29 \\times 5\\}$<br>
      $= 15\\{14 + 145\\}$<br>
      $= 15 \\times 159 = 2385$<br><br>
      <b>উত্তর:</b> 2385
    `
