    solution: `
      আমরা জানি, বৃত্তের কেন্দ্র থেকে ব্যাস ভিন্ন কোনো জ্যা-এর উপর অঙ্কিত লম্ব ঐ জ্যা-কে সমদ্বিখণ্ডিত করে।<br><br>
      সমকোণী ত্রিভুজ সূত্রানুসারে, অর্ধ-জ্যা এর দৈর্ঘ্য:<br>
      $= \\sqrt{\\text{ব্যাসার্ধ}^২ - \\text{লম্ব দূরত্ব}^২}$<br>
      $= \\sqrt{১৩^২ - ৫^২} = \\sqrt{১৬৯ - ২৫} = \\sqrt{১৪৪} = ১২$ সে.মি.<br><br>
      $\\therefore$ জ্যা এর সম্পূর্ণ দৈর্ঘ্য = $(১২ \\times ২) = ২৪$ সে.মি.।<br><br>
      <b>উত্তর:</b> ২৪ সে.মি.
    `
