    question: "৬০ মিটার দীর্ঘ একটি ট্রেনের গতিবেগ ঘণ্টায় ৪৮ কি.মি.। রেললাইনের পাশের একটি খুঁটিকে অতিক্রম করতে ট্রেনটির কত সময় লাগবে?",
    solution: `
      খুঁটিটিকে অতিক্রম করতে ট্রেনটিকে তার নিজের দৈর্ঘ্যের সমান দূরত্ব অতিক্রম করতে হবে।<br>
      অতিক্রান্ত দূরত্ব = ৬০ মিটার।<br><br>
      ট্রেনের গতিবেগ = ৪৮ কি.মি./ঘণ্টা<br>
      $= \\frac{৪৮ \\times ১০০০}{৩৬০০}$ মিটার/সেকেন্ড<br>
      $= \\frac{৪০}{৩}$ মিটার/সেকেন্ড<br><br>
      $\\therefore$ প্রয়োজনীয় সময় = $\\frac{\\text{দূরত্ব}}{\\text{গতিবেগ}}$<br>
      $= \\frac{৬০}{\\frac{৪০}{৩}} = \\frac{৬০ \\times ৩}{৪০} = \\frac{১৮০}{৪০} = ৪.৫$ সেকেন্ড।<br><br>
      <b>উত্তর:</b> ৪.৫ সেকেন্ড।
    `
