    postType: "অফিস সহকারী কাম-কম্পিউটার মুদ্রাক্ষরিক",
    source: "ইমিগ্রেশন ও পাসপোর্ট অধিদপ্তর",
    examYear: "২০২৫",
    question: "যদি $x - \\frac{1}{x} = 5$ হয়, তবে $\\frac{x^4 + 1}{x^2}$ এর মান কত?",
    solution: `
      প্রদত্ত রাশি $= \\frac{x^4 + 1}{x^2}$<br>
      $= \\frac{x^4}{x^2} + \\frac{1}{x^2}$<br>
      $= x^2 + \\frac{1}{x^2}$<br>
      $= \\left(x - \\frac{1}{x}\\right)^2 + 2 \\cdot x \\cdot \\frac{1}{x}$<br>
      $= (5)^2 + 2$<br>
      $= 25 + 2 = 27$<br><br>
      <b>উত্তর:</b> 27
    `
