    question: "৮৪ টাকা কত টাকার ১২.৫০%?",
    solution: `
      মনে করি, সংখ্যাটি $x$ টাকা।<br><br>
      প্রশ্নমতে,<br>
      $x \\times ১২.৫০\\% = ৮৪$<br>
      $\\Rightarrow x \\times \\frac{১২.৫}{১০০} = ৮৪$<br>
      $\\Rightarrow x \\times \\frac{১}{৮} = ৮৪$<br>
      $\\therefore x = ৮৪ \\times ৮ = ৬৭২$ টাকা।<br><br>
      <b>উত্তর:</b> ৬৭২ টাকা।
    `
