    examYear: "২০২৫",
    question: "$x + y = 4$ হলে, $x^3 + y^3 + 12xy$ এর মান কত?",
    solution: `
      প্রদত্ত রাশি $= x^3 + y^3 + 12xy$<br>
      $= (x + y)^3 - 3xy(x + y) + 12xy$<br><br>
      $x + y = 4$ বসিয়ে পাই:<br>
      $= (4)^3 - 3xy(4) + 12xy$<br>
      $= 64 - 12xy + 12xy = 64$<br><br>
      <b>উত্তর:</b> 64
    `
