    chapterId: 15, // অধ্যায় ১৫: সূত্রের সাহায্যে গুণফল
    category: "সরল ও মান নির্ণয়",
    postType: "অফিস সহকারী কাম-কম্পিউটার মুদ্রাক্ষরিক",
    source: "গণপূর্ত অধিদপ্তর",
    examYear: "২০২৫",
    question: "সূত্রের সাহায্যে $(x^2 + 2)$ ও $(x^4 - 2x^2 + 4)$ এর গুণফল নির্ণয় করুন।",
    solution: `
      প্রদত্ত গুণফল $= (x^2 + 2)(x^4 - 2x^2 + 4)$<br>
      $= (x^2 + 2)\\{(x^2)^2 - (x^2)(2) + 2^2\\}$<br>
      আমরা জানি, $(a + b)(a^2 - ab + b^2) = a^3 + b^3$<br>
      $= (x^2)^3 + 2^3$<br>
      $= x^6 + 8$<br><br>
      <b>উত্তর:</b> $x^6 + 8$
    `
