    id: 768,
    chapterId: 6, // অধ্যায় ০৬: দুই চলকের সমীকরণ (অঙ্ক সংক্রান্ত)
    category: "সংখ্যার সমীকরণ",
    postType: "অফিস সহকারী কাম-কম্পিউটার মুদ্রাক্ষরিক",
    source: "গণপূর্ত অধিদপ্তর",
    examYear: "২০২৫",
    question: "দুই অঙ্কবিশিষ্ট কোনো সংখ্যার একক স্থানীয় অঙ্কটি দশক স্থানীয় অঙ্ক অপেক্ষা ২ বেশি। অঙ্কদ্বয় স্থান বিনিময় করলে যে সংখ্যা পাওয়া যাবে তা প্রদত্ত সংখ্যার দ্বিগুণ অপেক্ষা ৬ কম হবে। সংখ্যাটি নির্ণয় করুন।",
    solution: `
      মনে করি, দশক স্থানীয় অঙ্কটি = $x$<br>
      $\\therefore$ একক স্থানীয় অঙ্কটি = $(x + ২)$<br>
      $\\therefore$ মূল সংখ্যাটি = $১০x + (x + ২) = ১১x + ২$<br><br>
      অঙ্কদ্বয় স্থান বিনিময় করলে সংখ্যাটি হয়:<br>
      $= ১০(x + ২) + x = ১০x + ২০ + x = ১১x + ২০$<br><br>
      প্রশ্নমতে,<br>
      $১১x + ২০ = ২(১১x + ২) - ৬$<br>
      $\\Rightarrow ১১x + ২০ = ২২x + ৪ - ৬$<br>
      $\\Rightarrow ১১x + ২০ = ২২x - ২$<br>
      $\\Rightarrow ২২x - ১১x = ২০ + ২$<br>
      $\\Rightarrow ১১x = ২২$<br>
      $\\therefore x = ২$<br><br>
      $\\therefore$ একক স্থানীয় অঙ্ক = $২ + ২ = ৪$<br>
      $\\therefore$ নির্ণেয় সংখ্যাটি = $(১১ \\times ২ + ২) = ২৪$<br><br>
      <b>উত্তর:</b> ২৪
    `
