    chapterId: 8, // অধ্যায় ০৮: চক্রবৃদ্ধি হারে জনসংখ্যা বৃদ্ধি
    category: "মুনাফা আসল",
    postType: "সাঁটমুদ্রাক্ষরিক-কাম-কম্পিউটার অপারেটর",
    source: "গণপূর্ত অধিদপ্তর",
    examYear: "২০২৫",
    question: "কোনো শহরের বর্তমান জনসংখ্যা ৮০ লক্ষ। ঐ শহরের জনসংখ্যা বৃদ্ধির হার প্রতি হাজারে ৩০ হলে, ৩ বছর পর ঐ শহরের জনসংখ্যা কত হবে?",
    solution: `
      বর্তমান জনসংখ্যা ($P$) = ৮০,০০,০০০ জন<br>
      বৃদ্ধির হার ($r$) = প্রতি হাজারে ৩০ $= \\frac{৩০}{১০০০} = \\frac{৩}{১০০}$<br>
      সময় ($n$) = ৩ বছর<br><br>
      আমরা জানি, $C = P(1 + r)^n$<br>
      $= ৮০,০০,০০০ \\times \\left(১ + \\frac{৩}{১০০}\\right)^৩$<br>
      $= ৮০,০০,০০০ \\times \\left(\\frac{১০৩}{১০০}\\right)^৩$<br>
      $= ৮০,০০,০০০ \\times \\frac{১০৯২৭২৭}{১,০০,০০,০০}$<br>
      $= ৮ \\times ১০৯২৭২৭ = ৮৭,৪১,৮১৬$ জন।<br><br>
      <b>উত্তর:</b> ৮৭,৪১,৮১৬ জন।
    `
