    id: 773,
    chapterId: 21, // অধ্যায় ২১: জ্যামিতি (বেলন বা সিলিন্ডারের বক্রপৃষ্ঠ)
    category: "জ্যামিতি",
    postType: "সাঁটমুদ্রাক্ষরিক-কাম-কম্পিউটার অপারেটর",
    source: "গণপূর্ত অধিদপ্তর",
    examYear: "২০২৫",
    question: "একটি সমবৃত্ত বেলনের ব্যাসার্ধ ৪.৫ সে.মি. ও উচ্চতা ৬ সে.মি. হলে বেলনটির বক্রপৃষ্ঠের ক্ষেত্রফল নির্ণয় করুন। ($\\pi = 3.14$)",
    solution: `
      দেওয়া আছে,<br>
      ব্যাসার্ধ ($r$) = ৪.৫ সে.মি.<br>
      উচ্চতা ($h$) = ৬ সে.মি.<br><br>
      আমরা জানি, সমবৃত্ত বেলনের বক্রপৃষ্ঠের ক্ষেত্রফল = $2\\pi rh$<br>
      $= ২ \\times ৩.১৪ \\times ৪.৫ \\times ৬$<br>
      $= ১৬৯.৫৬$ বর্গ সে.মি.।<br><br>
      <b>উত্তর:</b> ১৬৯.৫৬ বর্গ সে.মি.
    `
