    chapterId: 15, // অধ্যায় ১৫: সূত্রের সাহায্যে গুণফল
    category: "সরল ও মান নির্ণয়",
    postType: "সাঁটমুদ্রাক্ষরিক-কাম-কম্পিউটার অপারেটর",
    source: "গণপূর্ত অধিদপ্তর",
    examYear: "২০২৫",
    question: "সূত্রের সাহায্যে $(4a - 5b)$ ও $(16a^2 + 20ab + 25b^2)$ এর গুণফল নির্ণয় করুন।",
    solution: `
      প্রদত্ত রাশি $= (4a - 5b)(16a^2 + 20ab + 25b^2)$<br>
      $= (4a - 5b)\\{(4a)^2 + (4a)(5b) + (5b)^2\\}$<br>
      আমরা জানি, $(x - y)(x^2 + xy + y^2) = x^3 - y^3$<br>
      $= (4a)^3 - (5b)^3$<br>
      $= 64a^3 - 125b^3$<br><br>
      <b>উত্তর:</b> $64a^3 - 125b^3$
    `
