    question: "$x^3 - 2x^2$, $x^2 - 4$ এবং $xy - 2y$ এর গ.সা.গু নির্ণয় করুন।",
    solution: `
      ১ম রাশি $= x^3 - 2x^2 = x^2(x - 2)$<br>
      ২য় রাশি $= x^2 - 4 = (x + 2)(x - 2)$<br>
      ৩য় রাশি $= xy - 2y = y(x - 2)$<br><br>
      $\\therefore$ সাধারণ গুণনীয়ক (গ.সা.গু) $= x - 2$<br><br>
      <b>উত্তর:</b> $x - 2$
    `
