    question: "উৎপাদকে বিশ্লেষণ করুন: $x^2 - 2x - 15$",
    solution: `
      প্রদত্ত রাশি $= x^2 - 2x - 15$<br>
      $= x^2 - 5x + 3x - 15$<br>
      $= x(x - 5) + 3(x - 5)$<br>
      $= (x - 5)(x + 3)$<br><br>
      <b>উত্তর:</b> $(x - 5)(x + 3)$
    `
