    examYear: "২০২৫",
    question: "৯.৮ মি. ব্যাসের বৃত্তাকার একটি বাগানের ক্ষেত্রফল কত?[cite: 3]",
    solution: `
      বৃত্তাকার বাগানের ব্যাস $2r = ৯.৮$ মি.<br>
      $\\therefore$ ব্যাসার্ধ $r = \\frac{৯.৮}{২} = ৪.৯$ মি.<br><br>
      $\\therefore$ ক্ষেত্রফল $= \\pi r^2$<br>
      $= ৩.১৪ \\times (৪.৯)^২$<br>
      $= ৩.১৪ \\times ২৪.০১ \\approx ৭৫.৩৯$ বর্গমিটার (প্রায়)।<br><br>
      <b>উত্তর:</b> ৭৫.৩৯ বর্গমি. (প্রায়)।
    `
