    source: "গণপূর্ত অধিদপ্তর",
    examYear: "২০২৫",
    question: "$24x^3 - 81y^3$ কে উৎপাদকে বিশ্লেষণ করুন।[cite: 3]",
    solution: `
      প্রদত্ত রাশি $= 24x^3 - 81y^3$<br>
      $= 3(8x^3 - 27y^3)$<br>
      $= 3\\{(2x)^3 - (3y)^3\\}$<br>
      $= 3(2x - 3y)\\{(2x)^2 + (2x)(3y) + (3y)^2\\}$<br>
      $= 3(2x - 3y)(4x^2 + 6xy + 9y^2)$<br><br>
      <b>উত্তর:</b> $3(2x - 3y)(4x^2 + 6xy + 9y^2)$
    `
