    chapterId: 15, // অধ্যায় ১৫: সরল ও মান নির্ণয়
    category: "সরল ও মান নির্ণয়",
    postType: "নকশাকার",
    source: "গণপূর্ত অধিদপ্তর",
    examYear: "২০২৫",
    question: "$x + y = 4$ হলে, $x^3 + y^3 + 12xy$ এর মান কত?[cite: 3]",
    solution: `
      প্রদত্ত রাশি $= x^3 + y^3 + 12xy$<br>
      $= (x + y)^3 - 3xy(x + y) + 12xy$<br><br>
      $x + y = 4$ বসিয়ে পাই:<br>
      $= (4)^3 - 3xy(4) + 12xy$<br>
      $= 64 - 12xy + 12xy$<br>
      $= 64$<br><br>
      <b>উত্তর:</b> 64
    `
