    chapterId: 3, // অধ্যায় ০৩: নল ও চৌবাচ্চা
    category: "পাইপ ও চৌবাচ্চা",
    postType: "বেঞ্চ সহকারী",
    source: "শ্রম ও কর্মসংস্থান মন্ত্রণালয়",
    examYear: "২০২৫",
    question: "একটি নল ১২ মিনিটে একটি খালি চৌবাচ্চা পূর্ণ করতে পারে। অপর একটি নল প্রতি মিনিটে ১৪ লিটার পানি বের করে দেয়। চৌবাচ্চাটি খালি থাকা অবস্থায় দুইটি নল একসঙ্গে খুলে দেওয়া হয় এবং চৌবাচ্চাটি ৯৬ মিনিটে পূর্ণ হয়। চৌবাচ্চাটিতে কত লিটার পানি ধরে?[cite: 3]",
    solution: `
      মনে করি, চৌবাচ্চাটিতে পানি ধরে $x$ লিটার।<br><br>
      ১ম নল ১২ মিনিটে পূর্ণ করে $x$ লিটার<br>
      $\\therefore$ ১ম নল ১ মিনিটে পূর্ণ করে $\\frac{x}{১২}$ লিটার<br><br>
      উভয় নল একসঙ্গে ৯৬ মিনিটে পূর্ণ করে $x$ লিটার<br>
      $\\therefore$ ১ মিনিটে পূর্ণ হয় $\\frac{x}{৯৬}$ লিটার<br><br>
      প্রশ্নমতে,<br>
      $\\frac{x}{১২} - \\frac{x}{৯৬} = ১৪$<br>
      $\\Rightarrow \\frac{৮x - x}{৯৬} = ১৪$<br>
      $\\Rightarrow \\frac{৭x}{৯৬} = ১৪$<br>
      $\\Rightarrow ৭x = ১৩৪৪$<br>
      $\\therefore x = \\frac{১৩৪৪}{৭} = ১৯২$ লিটার।<br><br>
      <b>উত্তর:</b> ১৯২ লিটার।
    `
