    solution: `
      ২৫% বৃদ্ধিতে চিনির বর্তমান মূল্য = $(১০০ + ২৫) = ১২৫$ টাকা<br><br>
      ব্যয় অপরিবর্তিত রাখতে ১২৫ টাকায় কমাতে হবে ২৫ টাকা<br>
      $\\therefore$ ১ টাকায় কমাতে হবে = $\\frac{২৫}{১২৫}$ টাকা<br>
      $\\therefore$ ১০০ টাকায় কমাতে হবে = $\\frac{২৫ \\times ১০০}{১২৫} = ২০$ টাকা।<br><br>
      <b>উত্তর:</b> ২০%
    `
