    question: "একটি ট্রেন ঘণ্টায় ৪৮ কি.মি. বেগে চলে ৩৬০ মিটার দীর্ঘ একটি প্ল্যাটফর্ম ১ মিনিটে অতিক্রম করে। ট্রেনটির দৈর্ঘ্য কত?[cite: 4]",
    solution: `
      ট্রেনের গতিবেগ = ৪৮ কি.মি./ঘণ্টা<br>
      $= \\frac{৪৮ \\times ১০০০}{৩৬০০}$ মিটার/সেকেন্ড $= \\frac{৪০}{৩}$ মিটার/সেকেন্ড<br><br>
      ১ মিনিট বা ৬০ সেকেন্ডে অতিক্রান্ত মোট দূরত্ব:<br>
      $= \\frac{৪০}{৩} \\times ৬০ = ৮০০$ মিটার<br><br>
      আমরা জানি, প্ল্যাটফর্ম অতিক্রম করতে ট্রেনকে নিজের দৈর্ঘ্য + প্ল্যাটফর্মের দৈর্ঘ্য অতিক্রম করতে হয়।<br>
      $\\therefore$ ট্রেনের দৈর্ঘ্য = মোট দূরত্ব $-$ প্ল্যাটফর্মের দৈর্ঘ্য<br>
      $= ৮০০ - ৩৬০ = ৪৪০$ মিটার।<br><br>
      <b>উত্তর:</b> ৪৪০ মিটার।
    `
