    question: "ক, খ ও গ ২৮০ টাকা নিয়ে ব্যবসা শুরু করল। ক ও খ এর মূলধন সমান কিন্তু গ এর মূলধন ২০ টাকা কম। মোট ৫৬ টাকা লাভ হলে গ কত টাকা লাভ পাবে?[cite: 4]",
    solution: `
      মনে করি, ক এর মূলধন = $x$ টাকা<br>
      $\\therefore$ খ এর মূলধন = $x$ টাকা<br>
      এবং গ এর মূলধন = $(x - ২০)$ টাকা<br><br>
      প্রশ্নমতে,<br>
      $x + x + (x - ২০) = ২৮০$<br>
      $\\Rightarrow ৩x - ২০ = ২৮০$<br>
      $\\Rightarrow ৩x = ৩০০$<br>
      $\\therefore x = ১০০$<br><br>
      $\\therefore$ ক এর মূলধন = ১০০ টাকা, খ এর মূলধন = ১০০ টাকা এবং গ এর মূলধন = $(১০০ - ২০) = ৮০$ টাকা<br><br>
      তাদের মূলধনের অনুপাত ক : খ : গ = ১০০ : ১০০ : ৮০ = ৫ : ৫ : ৪<br>
      অনুপাতের রাশিগুলোর যোগফল = $৫ + ৫ + ৪ = ১৪$<br><br>
      $\\therefore$ মোট ৫৬ টাকা লাভে গ পাবে = $৫৬ \\times \\frac{৪}{১৪} = ১৬$ টাকা।<br><br>
      <b>উত্তর:</b> ১৬ টাকা।
    `
