    category: "সরল ও মান নির্ণয়",
    postType: "অফিস সহায়ক",
    source: "জেলা প্রশাসকের কার্যালয়, খাগড়াছড়ি",
    examYear: "২০২৬",
    question: "সরল করুন: $(x + y)^2 + 2(x + y)(x - y) + (x - y)^2$[cite: 4]",
    solution: `
      ধরি, $x + y = a$ এবং $x - y = b$<br><br>
      প্রদত্ত রাশি $= a^2 + 2ab + b^2$<br>
      $= (a + b)^2$<br><br>
      মান বসিয়ে পাই:<br>
      $= \\{(x + y) + (x - y)\\}^2$<br>
      $= (2x)^2$<br>
      $= 4x^2$<br><br>
      <b>উত্তর:</b> $4x^2$
    `
