    question: "উৎপাদকে বিশ্লেষণ করুন: $x^2 + x - 56$[cite: 3]",
    solution: `
      প্রদত্ত রাশি $= x^2 + x - 56$<br>
      $= x^2 + 8x - 7x - 56$<br>
      $= x(x + 8) - 7(x + 8)$<br>
      $= (x + 8)(x - 7)$<br><br>
      <b>উত্তর:</b> $(x + 8)(x - 7)$
    `
