    examYear: "২০২৬",
    question: "একটি পরীক্ষায় ৬০% পরীক্ষার্থী পাস করেছে। অকৃতকার্যদের ১৫ জন বিদেশ চলে গেছে এবং ৪৫ জন ব্যবসা করে। কতজন পরীক্ষার্থী পরীক্ষায় অংশ নিয়েছিল?[cite: 3]",
    solution: `
      মোট ফেল বা অকৃতকার্য পরীক্ষার্থীর সংখ্যা = $(১৫ + ৪৫) = ৬০$ জন<br><br>
      শতকরা হিসেবে ফেল করা পরীক্ষার্থী = $(১০০\\% - ৬০\\%) = ৪০\\%$<br><br>
      প্রশ্নমতে,<br>
      পরীক্ষার্থীর ৪০% = ৬০ জন<br>
      $\\therefore$ মোট পরীক্ষার্থী (১০০%) = $\\frac{৬০ \\times ১০০}{৪০} = ১৫০$ জন।<br><br>
      <b>উত্তর:</b> ১৫০ জন।
    `
