    question: "০.০০৫, ০.০৫০০, ০.৫ এর মধ্যে কোনটি বড়?[cite: 3]",
    solution: `
      প্রদত্ত সংখ্যাগুলোকে সমদশমিক স্থানে রূপান্তর করে পাই:<br>
      $০.০০৫ = \\frac{৫}{১০০০}$<br>
      $০.০৫০০ = ০.০৫০ = \\frac{৫০}{১০০০}$<br>
      $০.৫ = ০.৫০০ = \\frac{৫০০}{১০০০}$<br><br>
      দেখা যাচ্ছে, লঘিষ্ঠ বা সমতুল্য ভগ্নাংশের বিচারে $০.৫০০ > ০.০৫০ > ০.০০৫$<br>
      $\\therefore$ সবচেয়ে বড় সংখ্যাটি হলো ০.৫।<br><br>
      <b>উত্তর:</b> ০.৫
    `
