    question: "$a + b = 6$ এবং $a - b = 4$ হলে, $ab$ এর মান কত?[cite: 3]",
    solution: `
      আমরা জানি,<br>
      $ab = \\left(\\frac{a + b}{2}\\right)^2 - \\left(\\frac{a - b}{2}\\right)^2$<br><br>
      দেওয়া মান বসিয়ে পাই:<br>
      $= \\left(\\frac{6}{2}\\right)^2 - \\left(\\frac{4}{2}\\right)^2$<br>
      $= (3)^2 - (2)^2$<br>
      $= 9 - 4 = 5$<br><br>
      <b>উত্তর:</b> 5
    `
