    question: "১৮টি ছাগলের দাম ৪টি গরুর দামের সমান হলে ৪৫টি ছাগলের পরিবর্তে কতটি গরু পাওয়া যাবে?[cite: 3]",
    solution: `
      ১৮টি ছাগলের পরিবর্তে পাওয়া যায় ৪টি গরু<br>
      $\\therefore$ ১টি ছাগলের পরিবর্তে পাওয়া যায় = $\\frac{৪}{১৮}$টি গরু<br>
      $\\therefore$ ৪৫টি ছাগলের পরিবর্তে পাওয়া যায় = $\\frac{৪ \\times ৪৫}{১৮} = \\frac{১৮০}{১৮} = ১০$টি গরু।<br><br>
      <b>উত্তর:</b> ১০টি।
    `
