    examYear: "২০২৬",
    question: "২৫ জন শ্রমিক একটি কাজ ১৪ দিনে শেষ করতে পারে। ১০ দিনে কাজটি শেষ করতে হলে নতুন কতজন শ্রমিক লাগবে?[cite: 3]",
    solution: `
      ১৪ দিনে কাজটি করতে শ্রমিক লাগে ২৫ জন<br>
      $\\therefore$ ১ দিনে কাজটি করতে শ্রমিক লাগে = $(২৫ \\times ১৪)$ জন<br>
      $\\therefore$ ১০ দিনে কাজটি করতে শ্রমিক লাগে = $\\frac{২৫ \\times ১৪}{১০} = ৩৫$ জন<br><br>
      $\\therefore$ নতুন অতিরিক্ত শ্রমিক লাগবে = $(৩৫ - ২৫) = ১০$ জন।<br><br>
      <b>উত্তর:</b> ১০ জন।
    `
