    solution: `
      দেওয়া আছে, $a^2 + b^2 = ab$<br>
      $\\Rightarrow a^2 - ab + b^2 = 0$<br><br>
      প্রদত্ত রাশি $= a^3 + b^3$<br>
      $= (a + b)(a^2 - ab + b^2)$<br>
      $= (a + b) \\times 0$<br>
      $= 0$<br><br>
      <b>উত্তর:</b> 0
    `
